INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words) VALUES
(401,'외국환중개회사','외국환중개회사는 외국통화의 매매·교환·대여의 중개, 외국통화를 기초자산으로 하는 파생상품거래의 중개 또는 이와 관련된 업무를 영위하는 자를 말한다.','외국환중개회사는 외국통화의 매매·교환·대여의 중개, 외국통화를 기초자산으로 하는 파생상품거래의 중개 또는 이와 관련된 업무를 영위하는 자를 말한다. 현재 외국환중개업무를 인가받은 기관으로는 서울외국환중개, 한국자금중개, KIDB자금중개, IPS외국환중개, Tullett Prebon 등이 있다. 외국환중개업무를 영위하려면 자본·시설 및 전문인력에 관한 증빙서류 등을 기획재정부장관에게 제출하여 인가를 받아야 한다. 인가요건으로는 40억원 이상의 납입자본금, 외국환중개업무 및 이에 관한 보고 등을 수행할 수 있는 전산시설, 업무수행에 필요한 2명 이상의 전문인력을 갖추어야 한다. 외국환중개회사는 외환시장에 서 하루 동안 거래된 외환의 거래량과 가격을 합산해서 가중평균한 시세인 시장평균환율을 다음 날 오전에 매매기준율로 고시하는데, 외국환은행들은 이 매매기준율을 참고하여여기에 수수료 등을 적용해 각각의 은행별 매매기준율을 결정한다. 이처럼 외국환중개회사는 우리나라 외환시스템에서 중요한 역할을 수행하고 있다.','','ㅇㄱㅎㅈㄱㅎㅅ',ARRAY['시장평균환율(MAR)']::text[]),
(402,'외국환평형기금','자국 통화가치의 안정을 도모하고 투기적인 외화 유출입에 따른 외환시장의 혼란을 방지할 목적으로 정부가 외환시장에 개입하는 데 사용하기 위하여 조성한 기금을 말한다.','자국 통화가치의 안정을 도모하고 투기적인 외화 유출입에 따른 외환시장의 혼란을 방지할 목적으로 정부가 외환시장에 개입하는 데 사용하기 위하여 조성한 기금을 말한다. 대다수 국가에서 유사한 형태로 동 기금을 설치·운용하고 있는데 미국에서는 Exchange Stabilization Fund, 영국에서는 Exchange Equalization Fund라고 부르며 우리나라에 서는 외국환평형기금(Exchange Equalization Fund)이라고 부르고 있다. 우리나라의 외국환평형기금은 외화기금계정과 원화기금계정으로 구분되어 한국은행에 설치되어 있다. 한편 외국환평형기금의 소요자금은 주로 공공자금관리기금으로부터의 예수금, 외화표시외국환평형기금채권 발행을 통하여 조달한다. 자금의 운용은 주로 한국은행에의 예치, 한 국투자공사(KIC)에 대한 위탁의 형태로 이루어지고 있다.','','ㅇㄱㅎㅍㅎㄱㄱ',ARRAY['외환시장']::text[]),
(403,'외국환포지션','외국환포지션은 일정 시점에 외국환은행 및 기업 등이 보유하고 있는 외화표시자산과 부채의 차액으로서 거래 주체가 환리스크에 노출된 정도를 나타낸다.','외국환포지션은 일정 시점에 외국환은행 및 기업 등이 보유하고 있는 외화표시자산과 부채의 차액으로서 거래 주체가 환리스크에 노출된 정도를 나타낸다. 외국환포지션에 서 외화자산이 외화부채를 초과하는 상황을 매입초과포지션(over-bought position 또는 long position), 외화부채가 외화자산을 초과하는 상황을 매도초과포지션(over-sold position 또는 short position), 그리고 외화자산과 외화부채가 균형을 이루는 상황을 스퀘어포지션(square position)이라 한다. 한편 외국환포지션은 포지션 산정에 있어 포함 되는 자산의 범위에 따라 현물환포지션(현물자산-현물부채), 선물환포지션(선물자산-선물부채), 그리고 현물환포지션과 선물환포지션을 합산한 종합포지션으로 구분되고 있다. 외환당국은 개별 은행의 건전한 경영을 유도하고 과도한 외국환포지션 구축으로 인한 외환시장 교란을 방지하기 위하여 각 외국환은행별 외국환포지션 한도를 설정, 관리하고 있다.','','ㅇㄱㅎㅍㅈㅅ',ARRAY['외환시장','외국환포지션한도']::text[]),
(404,'외국환포지션한도','외국환은행의 외화자산과 외화부채가 일치하지 않을 경우 환율변동 위험에 노출되어 이 에 따른 손익이 발생한다.','외국환은행의 외화자산과 외화부채가 일치하지 않을 경우 환율변동 위험에 노출되어 이 에 따른 손익이 발생한다. 예를 들면 외국환은행이 달러매입초과포지션인 상황에서 환율이 상승하면 이익을 보게 되나 환율이 하락하면 손실을 입게 된다. 반대로 매도초과 포지션일 경우 환율상승 시 손실을, 환율하락 시 이익을 보게 된다. 한 외국환은행의 과도한 외국환포지션은 외환시장내 교란요인으로 작용할 수 있다. 이에 따라 우리나라는 외국환은행의 건전 경영을 유도하고 외환시장 교란을 사전에 방지하기 위하여 외환매입초과포지션 또는 외환매도초과포지션의 한도를 설정하는 외국환포지션관리제도를 운영하고 있다. 종합포지션과 선물환포지션에 대해 관리하고 있는데, 2025년 6월 말 현재 종합포지션한도는 전월 말 자기자본의 50%, 선물환포지션한도는 국내은행의 경우 전월 말 자기자본의 75%, 외은지점은 전월 말 자기자본의 375% 이내이다.','','ㅇㄱㅎㅍㅈㅅㅎㄷ',ARRAY['외국환포지션','선물환포지션비율 규제','외환시장']::text[]),
(405,'외부자금','기업은 투자나 운영자금을 기업내부 또는 기업외부에서 조달하는데 금융기관 차입금, 사채발행 등 기업외부에서 조달된 자금을 외부자금이라 한다.','기업은 투자나 운영자금을 기업내부 또는 기업외부에서 조달하는데 금융기관 차입금, 사채발행 등 기업외부에서 조달된 자금을 외부자금이라 한다. 외부자금은 내부유보나 감가 상각충당금 등과 같은 내부자금과는 달리 자금의 이용가능 기간의 면에서 제약을 받으며, 자금조달에도 절차나 경비가 필요한 불리한 점도 있다. 반면, 자본시장의 상황에 따라 조달의 곤란도는 다르나 내부자금에서와 같은 자금량의 절대금액의 한계는 없으며, 또 여러종류의 조달가능성과 조달조건이 있어 적기에 이용할 수 있다는 이점이 있다. 따라서 기업은 자금수요의 상태에 따라 외부자금을 적절히 조달하여, 기업의 재무적 안전성을 유지하도록 하는 것이 중요하다. 통상 기업들의 고정투자 규모가 커질수록 외부자금 수요가 커지면서 내부자금보다 외부자금 조달 비중이 상대적으로 높아지는 경향을 보인다.','','ㅇㅂㅈㄱ',ARRAY['내부자금']::text[]),
(406,'외부효과','어떤 경제주체의 행위가 본인의 의도와는 관계없이 다른 경제주체에게 의도하지 않은 혜택이나 손해를 발생시키지만 그 영향에 대한 보상이 이루어지지 않는 현상을 말한다.','어떤 경제주체의 행위가 본인의 의도와는 관계없이 다른 경제주체에게 의도하지 않은 혜택이나 손해를 발생시키지만 그 영향에 대한 보상이 이루어지지 않는 현상을 말한다. 외부효과(Externality)는 긍정적인 효과와 부정적인 효과로 구분된다. 부정적 외부효과 (negative externality)는 자동차의 배기가스나 소음, 공장의 매연이나 폐수 등과 같이 제 3자의 경제적 후생수준을 낮추는 외부효과로 외부불경제(external diseconomy)라고 도 한다. 반면 교육에 따른 편익, 신기술의 개발에 따른 파급효과 등과 같이 제3자에게 이 득을 주는 외부효과를 긍정적 외부효과(positive externality) 또는 외부경제(external economy)라고 한다. 외부효과가 생기면 이에 대한 대가나 비용을 시장에서 지불하지 않아도 되기 때문에 해로운 외부효과를 만들어 내는 개인이나 기업은 굳이 외부효과를 줄이 려 하지 않게 되며, 이로운 외부효과를 만들어내는 개인이나 기업도 굳이 외부효과를 많이 만들어 낼 필요성을 느끼지 못하게 돼 외부효과를 시장에만 맡겨놓을 경우 전체적인자원배분이 비효율적으로 될 수 있다.','','ㅇㅂㅎㄱ',ARRAY['역선택','정보의 비대칭성']::text[]),
(407,'외화자금시장','외환시장이 이종통화 간 매매가 수반되고 환율이 매개변수가 되는 시장을 의미하는 반면외화자금시장은 금리를 매개변수로 하여 외환의 대출과 차입이 이루어지는 시장을 말한 다.','외환시장이 이종통화 간 매매가 수반되고 환율이 매개변수가 되는 시장을 의미하는 반면외화자금시장은 금리를 매개변수로 하여 외환의 대출과 차입이 이루어지는 시장을 말한 다. 대표적인 외화자금시장으로는 스왑(외환스왑 및 통화스왑)시장이 있는데 스왑거래의 경우 외환의 매매 형식을 취하고 있으나 실질적으로는 금리를 매개로 하여 여유통화를 담보로 필요통화를 차입한다는 점에서 대차거래라고 볼 수 있다. 이외에도 은행 간에 초단기로 외화의 차입 및 대여가 이루어지는 외화콜시장과 1년물 이내의 기간물 대차거래가 이루어지는 단기대차시장 등이 외화자금시장의 범주에 속한다. 은행 간 외화예치거래도 넓은 의미에서 외화자금시장으로 볼 수 있으나 런던이나 싱가포르와 같은 국제중심지와 달리 우리나라는 외화예치거래가 활발하지 않은 편이다. 한편 외화자금시장도 넓은 의미에서는 외환시장에 포함되는 것으로 볼 수 있다.','','ㅇㅎㅈㄱㅅㅈ',ARRAY['외환시장','외환스왑거래','통화스왑']::text[]),
(408,'외환건전성부담금제도','동아시아 외환위기, 글로벌 금융위기 등 우리나라가 겪었던 금융위기는 호황기에는 자본이 과도하게 유입되고 불황기에는 급격히 유출되는 자본유출입의 변동성에 주로 기인하였다.','동아시아 외환위기, 글로벌 금융위기 등 우리나라가 겪었던 금융위기는 호황기에는 자본이 과도하게 유입되고 불황기에는 급격히 유출되는 자본유출입의 변동성에 주로 기인하였다. 이에 따라 정부와 한국은행은 금융·외환위기의 재발을 방지하기 위하여 과도한 자본유출입의 변동성을 제어하는 한편 우리 경제의 거시건전성을 제고하기 위한 방안으로 외환부문 거시건전성정책 수단을 도입하게 되었는데, 이의 일환으로 2011년 8월에 외환건전성부담금제도를 도입·시행하였다. 외환건전성부담금제도는 과도한 외화차입을 억제하고 외채구조의 장기화를 유도하기 위하여 은행의 비예금성외화부채(=전체외화부채-외화예수금-경과성자금 등)를 대상으로 계약 만기별로 0.02∼0.2%의 부담금을 부과하였으며 적립된 부담금은 외국환평형기금에 귀속되어 위기 시 금융기관에 대한 외화유동성지원에 활용되도록 하고 있다. 2015년 7월 금융업권 간 형평성을 제고하고 부과체계를','','ㅇㅎㄱㅈㅅㅂㄷㄱㅈㄷ','{}'::text[]),
(409,'외환동시결제(PVP)','단순화하기 위하여 외환건전성부담금의 부과대상 및 부과요율 체계를 중심으로 제도를 개편하였으며, 현재는 만기 1년 이내의 비예금성외화부채에 대해 0.1%의 부담금을 부과 하고 있다.','단순화하기 위하여 외환건전성부담금의 부과대상 및 부과요율 체계를 중심으로 제도를 개편하였으며, 현재는 만기 1년 이내의 비예금성외화부채에 대해 0.1%의 부담금을 부과 하고 있다.','','ㅇㅎㄷㅅㄱㅈ()',ARRAY['외환결제리스크','Herstatt 리스크','CLS은행']::text[]),
(410,'외환보유액','외환보유액(Official Reserve Assets)은 중앙은행이나 정부가 국제수지 불균형을 보전하거나 외환시장 안정을 위해 언제든지 사용할 수 있도록 보유하고 있는 교환성이 있고 유동성이나…','외환보유액(Official Reserve Assets)은 중앙은행이나 정부가 국제수지 불균형을 보전하거나 외환시장 안정을 위해 언제든지 사용할 수 있도록 보유하고 있는 교환성이 있고 유동성이나 시장성이 높은 대외지급준비자산을 말한다. 그러므로 외환보유액은 긴급한 상황에서 쓰기 위해 갖고 있는 비상금과 같은 성격의 준비자산으로 외환보유액은 환율 급등 시 외환시장 안정을 위한 재원으로 이용될 뿐만 아니라 금융기관의 해외차입이 어려워지는 신용위기 상황에서 중앙은행 등이 최종대부자(last resort)의 역할을 하기 위한 재원이 된다. 이러한 목적에 부합하도록 현재 우리나라의 외환보유액은 선진국 국채 등 외화증권이나 예치금과 같은 유동성과 안정성이 높은 자산으로 운용되고 있다. 외환보유액은 경제위기 시 안전판 역할을 하여 국가 신용도를 높이고 중앙은행은 외화자산 운용에 따른 수익이 발생하는 등의 편익이 있지만 통화안정증권 등에 대한 이자지급 등 비용 또한 발생한다. 이처럼 외환보유의 편익과 기회비용이 동시에 발생하므로 외환보유액의 규모를 향후 발생 가능한 외부충격에 대한 완충 역할을 하는데 부족하지 않은 수준으로 적정 관리할 필요가 있다.','','ㅇㅎㅂㅇㅇ',ARRAY['대외지급준비자산','특별인출권(SDR)']::text[]),
(411,'외환스왑거래','외환스왑거래란 거래당사자들이 현재의 계약환율에 따라 서로 다른 통화를 교환하고 일정 기간 후 최초 계약 시점에서 정한 선물환율에 따라 원금을 재교환하는 거래를 말한다.','외환스왑거래란 거래당사자들이 현재의 계약환율에 따라 서로 다른 통화를 교환하고 일정 기간 후 최초 계약 시점에서 정한 선물환율에 따라 원금을 재교환하는 거래를 말한다. 즉 외환스왑거래는 동일한 거래상대방 간에 현물환과 선물환 또는 만기가 상이한 선물환과 선물환, 현물환과 현물환을 서로 반대 방향으로 동시에 매매하는 거래를 의미하며 스왑기간 중 이자 지급은 없으나 계약 시 통화 간 이자율 차가 반영되어 만기 시 환율이 산정된다. 외환스왑거래에 있어 매입·매도는 원일물(far date)거래를 기준으로 구분된다. 예를 들면 우리나라에서 외환스왑 매입은 달러화를 기준으로 근일물을 매도하고 원일물을 매입하는 sell&buy swap거래를 말하며 외환스왑 매도는 근일물을 매입하고 원일물을 매도하는 buy&sell swap거래를 의미한다. 외환스왑의 거래동기를 보면 자금조달, 환리스크의 관리, 결제일의 조정, 금리차익 획득 및 금리변동을 이용한 투기적 거래 등의 외환전산망목적으로 나누어 볼 수 있다.','','ㅇㅎㅅㅇㄱㄹ',ARRAY['스왑','선물환거래','통화스왑']::text[]),
(412,'외환시장','외환시장은 좁은 의미에서 외환의 수요와 공급이 연결되는 장소를 말하나 넓은 의미에서 는 이러한 장소적 개념뿐 아니라 외환거래의 형성, 결제 등 외환거래가 정기적 또는 지속적으로 이루어지는 일련의…','외환시장은 좁은 의미에서 외환의 수요와 공급이 연결되는 장소를 말하나 넓은 의미에서 는 이러한 장소적 개념뿐 아니라 외환거래의 형성, 결제 등 외환거래가 정기적 또는 지속적으로 이루어지는 일련의 메커니즘을 포괄한다. 외환시장은 기본적으로 서로 다른 통화로 표시된 지급수단의 매매가 이루어지는 시장(market for means of payments)으로서 외화자금의 대차가 이루어지는 외화자금시장과는 그 성격을 달리한다. 외환시장에서의 서로 다른 통화 간의 매매는 기본적으로 상품과 용역 그리고 금융자산의 매매거래에 수반하여 일어나기 때문에 이들 외환거래는 기본적으로 지급 메커니즘의 한 과정으로 이해할수 있다. 따라서 각국의 금융시장이나 유로금융시장에서 이루어지는 서로 다른 통화로 표시된 금융거래는 외환시장의 거래와 연계되어 이루어진다. 오늘날 국제외환시장은 세계주요 외환시장의 거래를 24시간 연계시키면서 모든 시장정보를 환율에 신속하게 그리고 지속적으로 반영하는 하나의 범세계적 시장으로서의 기능을 수행하면서 국제금융거래의 효율화를 촉진하고 있다.','','ㅇㅎㅅㅈ',ARRAY['외화자금시장']::text[]),
(413,'외환전산망','1997년 외환위기 이후 우리나라가 주식·채권시장을 전면 개방하고 외국인직접투자도 전면 허용하는 등 외환거래 자유화조치를 취함에 따라, 국외 여건 변화에 따른 빈번한 외자유출입 등으로 우리 경제의…','1997년 외환위기 이후 우리나라가 주식·채권시장을 전면 개방하고 외국인직접투자도 전면 허용하는 등 외환거래 자유화조치를 취함에 따라, 국외 여건 변화에 따른 빈번한 외자유출입 등으로 우리 경제의 변동성이 확대될 가능성이 크게 높아졌다. 이러한 위험에 효과적으로 대처할 수 있도록 외환거래 정보를 집중하고 이용할 수 있는 인프라의 구축필요성이 제기됨에 따라 정부는 1999년 3월 한국은행을 외환정보집중기관으로 지정하였고, 한국은행은 1999년 4월 외환거래 및 시장정보를 신속하게 수집·분석할 수 있는 외환정보시스템(FEIS; Foreign Exchange Information System, 이하 ‘외환전산망’)을 구축하였다. 외환전산망에는 외국환업무취급기관들이 실행한 외환거래 관련 통계 등 정보가 집중되며 한국은행은 이를 취합하여 기획재정부, 금융위원회, 국세청, 관세청, 금융정보분석원, 금융감독원 등 여러 이용기관들에게 신속하게 제공하고 있다. 한국은행은 외환전산망 자료를 활용해 국내외 외화자금 유출입 동향 등에 대한 신속한 모니터링과 시장안정을 위한 대응방안 마련, 국제수지·외채 등 주요 외환통계의 작성, 각종 불법적인 외환거래조사 등의 업무를 수행하고 있다.','','ㅇㅎㅈㅅㅁ',ARRAY['국제수지(BOP)','외채/대외채권']::text[]),
(414,'요소비용','국민소득을 평가하는 데는 두 가지 방법이 있다.','국민소득을 평가하는 데는 두 가지 방법이 있다. 하나는 시장가격에 의한 평가이고 다른하나는 요소비용(Factor Cost)에 의한 평가이다. 시장가격이란 상품이 시장에서 실제로 거래되고 있는 가격을 말하는 것으로서 여기에는 순생산 및 수입세(생산 및 수입세-보조금)가 포함되어 있다. 생산 및 수입세란 부가가치세나 특별소비세 등과 같이 우리가 상품을 살 때 상품가격에 포함되어 있는 세금을 말하며 보조금이란 기업이 상품을 만들 때 정부가 그 상품의 생산을 장려하기 위하여 생산비용 중 일부를 무상으로 제공해 주는 것을 말한다. 요소비용이란 시장가격에서 이와 같은 순생산 및 수입세를 공제한 것으로서 결국 그 상품을 만드는 데 들어간 생산요소에 대한 대가인 피용자보수와 영업잉여의 합계를 말한다. 이와 같이 생산의 요소비용을 측정하는 목적은 주로 투입된 생산요소의 생산성을 정확히 측정하는 데 있다.','','ㅇㅅㅂㅇ',ARRAY['요소비용 국민소득']::text[]),
(415,'요소비용 국민소득','요소비용에 의한 국민소득(NI at factor cost)은 통상 국민소득(NI)이라 불리며 한 나라의 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 토지…','요소비용에 의한 국민소득(NI at factor cost)은 통상 국민소득(NI)이라 불리며 한 나라의 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 토지, 자본, 경영에 대한 대가인 영업잉여의 합계로서 고정자본소모와 순생산 및 수입세가 포함되지 않으므로 한 나라 국민이 벌어들인 순수한 소득을 나타내는 지표이다. 요소비용에 의한 국민소득 = 시장가격에 의한 국민소득 - 생산 및 수입세 + 보조금 = 우발전환사채(코코본드) 피용자보수 + 영업잉여의 관계가 성립한다.','','ㅇㅅㅂㅇㄱㅁㅅㄷ',ARRAY['영업잉여','피용자보수']::text[]),
(416,'우발부채(채무)','과거에 발생한 원인은 있으나 채무의 확정이 미래 불확실한 사건의 발생 여부에 달려있는 잠재적 의무를 의미한다.','과거에 발생한 원인은 있으나 채무의 확정이 미래 불확실한 사건의 발생 여부에 달려있는 잠재적 의무를 의미한다. 또한 현재의무라고 하더라도 이를 이행하기 위해 경제적 가치가 있는 자원을 지출할 가능성이 높지 않거나 지출 가액을 신뢰성 있게 측정할 수 없는 경우도 포함한다. 예를 들면 대출약정, 지급보증, 계류 중인 소송사건 등이 이에 속한다. 즉 우발채무는 지급가능성, 채권자, 지급시기, 금액 등 불확실한 요소가 많기 때문에 재무제표에서 부채로 반영하지 않고 주석으로 기재한다. 우발부채(채무)는 매입채무, 차입금 등과 같이 채권자·지급시기·금액이 정해진 확정부채가 아니지만, 퇴직급여충당금 등 충당부채와 유사하다고 볼 수 있다. 그러나 충당부채는 결산일에 기업이 부담해야 할 의무가 명백히 존재하고 금액을 합리적으로 추정할 수 있다는 점에서 우발부채와는 확실하게 차이가 있다. 예를 들면 법원에 계류 중인 소송사건의 패소가능성은 우발채무에 속한다.','','ㅇㅂㅂㅊ(ㅊㅁ)','{}'::text[]),
(417,'우발전환사채(코코본드)','우발전환사채(Contingent Convertible Bond)는 발행기관이 경영개선명령을 받거나 부실금융기관으로 지정될 경우 상각되거나 보통주로 전환되는 조건이 부가되어 있는 채권…','우발전환사채(Contingent Convertible Bond)는 발행기관이 경영개선명령을 받거나 부실금융기관으로 지정될 경우 상각되거나 보통주로 전환되는 조건이 부가되어 있는 채권 (조건부자본증권)을 말한다. 이러한 조건이 실현될 경우 코코본드는 강제로 상각되거나 주식으로 전환되기 때문에 발행기관의 채무부담은 줄어들고 자본은 확충된다. 채권이 상각될 경우 투자자가 원금손실을 입게 되는 위험을 반영하여 코코본드의 발행금리는 일반회사채보다 다소 높게 형성된다. 최근 코코본드의 발행이 늘어난 것은 공급측면에서 무엇보다 바젤Ⅲ 시행에 따른 은행권의 자본확충 필요성이 증가한 데 기인한다. 바젤Ⅲ에서 는 금융기관 자본의 인정요건을 종전보다 강화하였는데, 특히 후순위채권 등에 대해서는 유사시 주식으로 전환되거나 상각되는 조건부자본 요건을 추가로 충족하도록 요구하고 있다. 바젤Ⅲ 규제 하에서 금융기관 입장에서는 코코본드를 발행하게 되면 자본이 증가 해 건전성지표인 자기자본비율이 개선되는 효과가 있다. 수요측면에서 보면, 코코본드는 지속되는 저금리 상황에서 일반 채권보다 금리가 높은 데다 이자지급이 보장되는 후순위채 위주로 발행됨에 따라 투자메리트가 높은 편이다. 코코본드 발행은 유사시 손쉽게 자본을 확충하는 이점이 있으나 발행기관의 자본조달비용을 증가시키는 효과도 있으므로 적정수준에서 관리될 필요가 있다.','','ㅇㅂㅈㅎㅅㅊ(ㅋㅋㅂㄷ)',ARRAY['자기자본비율']::text[]),
(418,'운영리스크','부적절하거나 잘못된 내부 프로세스(internal process), 인력, 시스템, 외부사건(external events) 등으로 인해 발생할 수 있는 손실 가능성을 말한다.','부적절하거나 잘못된 내부 프로세스(internal process), 인력, 시스템, 외부사건(external events) 등으로 인해 발생할 수 있는 손실 가능성을 말한다. 운영리스크(Operational Risk) 발생요인으로는 인력과 관련해서 인적 자원의 부족, 부적절한 직원, 교육 미실시, 실수 또는 의사소통상 오해 등이 있다. 프로세스와 관련해서는 부적절한 업무 분장, 과도 한 업무강도·과다한 업무량, 취약하거나 잘못된 프로세스, 복잡한 거래처리능력 부족 등 이 있다. 시스템과 관련해서는 시스템 장애, 취약한 시스템 설계, 데이터 보안구조 결함, 프로그램 오류 작동 등이 있다. 외부사건과 관련해서는 자연재해, 테러, 전쟁, 시설장애, 파업·데모·업무중단, 외부인의 범죄, 사기, 횡령, 경제환경 및 외부규제 등이 있다. 운영리스크의 결과로 발생가능한 손실에는 기업가치의 저하, 청구권손실, 손해배상, 법적지불책임, 규제조치, 자산손실 등이 있다.','','ㅇㅇㄹㅅㅋ','{}'::text[]),
(419,'워싱턴 컨센서스','1990년대 미국이 중남미 국가들에 대해 제시하였던 미국식 시장경제체제의 확산 전략을 뜻하며 미국이 주도하는 신자유주의의 대명사로도 인식되고 있다.','1990년대 미국이 중남미 국가들에 대해 제시하였던 미국식 시장경제체제의 확산 전략을 뜻하며 미국이 주도하는 신자유주의의 대명사로도 인식되고 있다. 이 용어는 1989년미국 국제경제연구소의 정치경제학자 존 윌리엄슨이 당시 경제위기로 어려움을 겪고 있던 중남미 국가들에 대한 개혁 처방을 워싱턴 컨센서스(Washington Consensus)로 명명한 데서 유래하였고 1990년대 초 미국의 재무부, 국제통화기금(IMF), 세계은행(World Bank) 등 미국 워싱턴에 있는 기관들의 논의를 거치면서 그 개념이 정립되었다. 워싱턴컨센서스는 개발도상국, 체제전환국, 제3세계 국가들이 시행해야 할 구조조정 정책으로 서 정부예산 삭감, 자본시장 자유화, 외환시장 개방, 관세 인하, 국가 기간산업 민영화, 원금리스크외국자본에 의한 국내기업 합병ㆍ매수 허용, 정부 규제 축소, 재산권 보호 등을 제시하고 있다. 실제로 이러한 정책들은 동구 사회주의국가의 체제 전환과 1990년대 후반 아시아의 외환위기 극복과정에서 채택되었다. 워싱턴 컨센서스에 대해서는 세계의 경제시스템을 미국의 자본과 기업이 진출하기 쉽게 만들어 미국의 이익을 증진시키기 위한 것이라는 비판도 있다.','','ㅇㅅㅌㅋㅅㅅㅅ',ARRAY['국제통화기금(IMF)','세계은행(World Bank)','동아시아 외환위기']::text[]),
(420,'워크아웃','기업과 금융기관의 협의로 진행되는 재무구조 개선과정 및 결과를 포괄적으로 이르는 말이다.','기업과 금융기관의 협의로 진행되는 재무구조 개선과정 및 결과를 포괄적으로 이르는 말이다. 부실기업을 정상기업으로 회생시키는 것이 목적으로 도산을 방지하기 위해 계약 불이행이 발생하였을 때 채무자와 채권자 간에 해결 방안을 모색하게 된다. 워크아웃 (Workout)은 기업 독자적으로 이행하기 어려운 기업 내부의 구조조정작업을 채권 금융기관이 주도하여 진행하며 그룹 내의 퇴출기업 선정, 자산매각, 주력사업 정비 등 광범위한 조처를 한다. 채무기업의 구조조정 노력에 대해 채권금융기관은 은행대출금의 출자전환, 대출금 상환유예, 이자감면, 부채삭감 등의 금융지원을 제공한다. 우리나라는 1997년외환위기 이후 자주 언급되었으며 대기업 구조조정 프로그램의 하나로 광범위하게 사용되었다. 한편 워크아웃과 대비되는 개념으로 기업회생절차가 있다. 기업, 금융기관 등 당사자간 협의를 중심으로 진행되는 워크아웃과 달리 기업회생절차는 법원의 결정(판결)을 통해 진행되는 보다 강력한 기업구조조정 절차이다.','','ㅇㅋㅇㅇ','{}'::text[]),
(421,'원/위안 직거래시장','원/위안 직거래시장은 달러를 매개로 하지 않고 원화를 위안화로, 위안화를 원화로 바로 환전할 수 있는 시장을 의미한다.','원/위안 직거래시장은 달러를 매개로 하지 않고 원화를 위안화로, 위안화를 원화로 바로 환전할 수 있는 시장을 의미한다. 2014년 7월 한·중 정상이 양국 간 자국 통화 거래를 활성화하는 것이 서로에게 이익이 된다는 데 인식을 같이하고 한ㆍ중 무역 및 금융거래에 서 위안화 활용도를 제고하기 위한 정책과제의 하나로 원/위안 직거래시장을 개설하기로 합의함에 따라 서울외환시장 운영협의회를 중심으로 중개시스템 개발, 시장조성자 제도 도입 등을 추진하여 2014년 12월 원/위안 직거래시장을 공식 개설하였다. 또한 2015년 10월 양국 정상회담을 통해 상하이 원/위안 직거래시장을 조속한 시일 내에 개설하기로 합의하였고 이에 따라 2016년 6월 27일 상하이 원/위안 직거래 시장이 개설되었다. 원/ 위안 직거래시장은 우리 경제 전반에 다양한 경제적 효과를 미친다. 우선 기업 등 고객은 미달러화의 매개 없이 원화와 위안화를 직거래함으로써 환전수수료 등 거래비용을 절감할 수 있다. 결제통화 다변화를 통해 미달러화 의존도가 낮아질 경우 미달러화 자금사정위험가중자산/위험가중치에 대한 우리경제의 민감도를 낮출 수 있다. 원/위안 직거래시장은 개설 이후 높은 관심과 시장조성은행들의 적극적거래 등에 힘입어 일평균 거래량이 30억 달러를 넘어서고 호가 스프레드도 경쟁적으로 형성되는 등 시장형성에 비교적 성공한 것으로 평가되고 있다.','','ㅇ/ㅇㅇㅈㄱㄹㅅㅈ',ARRAY['외환시장']::text[]),
(422,'원금리스크','외환결제리스크 중 가장 대표적인 리스크로 매도통화를 이미 지급하였거나 매도통화의 지급을 취소할 수 없는 상황에서 거래상대방이 파산하는 경우 매입통화를 전액 수취하지못하는 리스크를 원금리스크…','외환결제리스크 중 가장 대표적인 리스크로 매도통화를 이미 지급하였거나 매도통화의 지급을 취소할 수 없는 상황에서 거래상대방이 파산하는 경우 매입통화를 전액 수취하지못하는 리스크를 원금리스크(Principal Risk)라고 한다. 환거래가 양방향으로 일어난다는 점과 주로 국경을 넘어 발생한다는 특성으로 인하여 매입통화와 매도통화의 결제가 동시에 이루어지지 않기 때문에 원금리스크가 발생하게 된다.','','ㅇㄱㄹㅅㅋ',ARRAY['외환결제리스크','Herstatt 리스크']::text[]),
(423,'원금이자분리채권(STRIPS)','이표채의 원금과 미래의 이자금액을 분리하여 각각 무이표채(zero coupon bond)의 형태로 거래할 수 있는 채권을 말한다.','이표채의 원금과 미래의 이자금액을 분리하여 각각 무이표채(zero coupon bond)의 형태로 거래할 수 있는 채권을 말한다. 즉 채권의 원금과 이자를 분리하여 거래할 수 있는 채권이다. 만기에 한 번의 현금흐름만을 가지고 있기 때문에 이표채 채권에서 발생하는 재투자 위험이 제거되어 투자시점에서 확정 수익률을 보장받을 수 있으며 한 종목의 이표채가 원금이자분리채(STRIP; Separate Trading of Registered Interest and Principal of Securities)를 통해 다양한 만기의 무이표채로 전환됨에 따라 연기금, 보험 등 주요 기관투자가의 장기 무이표채에 대한 수요를 충족시킬 수 있다. 그리고 이표채권과 현금흐름이 동일한 원금이자분리채권 포트폴리오 간의 가격차이를 이용한 차익거래가 가능해진다. 다양한 만기와 수익률을 형성하게 되어 채권시장에 유동성을 증가시킬 수 있고 분리했을 때 각 채권 가치의 합과 재결합 상품 가치와의 차이에 의해 차익거래가 가능해 투자나 거래기법의 향상을 도모할 수 있다. 보통 원금부분을 P-STRIP, 이자부분을 C-STRIP이라고 한다.','','ㅇㄱㅇㅈㅂㄹㅊㄱ()',ARRAY['이표채','듀레이션']::text[]),
(424,'위조지폐','우리나라의 지폐는 한국은행의 의뢰에 따라 한국조폐공사가 제조하고 있는데 스캐너, 프린터 등을 이용하여 현용 지폐처럼 보이도록 만든 지폐를 위조지폐라고 한다.','우리나라의 지폐는 한국은행의 의뢰에 따라 한국조폐공사가 제조하고 있는데 스캐너, 프린터 등을 이용하여 현용 지폐처럼 보이도록 만든 지폐를 위조지폐라고 한다. 돈으로 사용하기 위해 지폐를 위조하는 행위는 국민경제에 커다란 혼란을 초래할 수 있으므로「형법」제207조에 따라 무기 또는 2년 이상 징역의 처벌을 받게 된다. 한편, 한국은행은 지폐의 위조를 예방하기 위해 홀로그램, 색변환잉크, 요판잠상, 미세문자, 숨은은선 등과 같은 위조방지장치를 지폐에 적용하고 있다.','','ㅇㅈㅈㅍ','{}'::text[]),
(425,'위험가중자산/위험가중치','자기자본비율 산출시 대차대조표상 자산계정의 단순 합계를 분모로 사용할 경우 자산을 구성하는 각 익스포저에 따른 리스크를 반영할 수 없는 문제가 있다.','자기자본비율 산출시 대차대조표상 자산계정의 단순 합계를 분모로 사용할 경우 자산을 구성하는 각 익스포저에 따른 리스크를 반영할 수 없는 문제가 있다. 그러므로 각 익스포저 금액에 해당 위험가중치를 곱하여 합산한 금액인 위험가중자산을 분모로 사용하게 된 다. 위험가중자산은 신용·시장·운영리스크로 구성된다. 각 리스크별 위험가중자산을 산출하는 방식은 바젤은행감독위원회(BCBS)가 제시한 방법을 따르는 표준방법과 은행의 자체 내부모형을 이용하는 방법으로 구분할 수 있다. 예를 들어 신용리스크 표준방법을 사용할 경우 익스포저에 거래상대방별 위험가중치를 곱한 금액을 합산하여 위험가중자산을 산출한다. 내부 모형을 사용하는 은행의 경우 자체 추정한 차주 부도율, 부도시 손실률, 부도시 익스포저 등을 사용하여 위험가중자산을 산출한다.','','ㅇㅎㄱㅈㅈㅅ/ㅇㅎㄱㅈㅊ',ARRAY['BIS 자기자본비율','익스포저','내부등급법']::text[]),
(426,'위험회피심리','일반적으로 투자자들이 동일한 기대현금흐름에 대해 보다 덜 위험한 투자안을 선호하는 경향을 위험회피(Risk Aversion)심리라고 한다.','일반적으로 투자자들이 동일한 기대현금흐름에 대해 보다 덜 위험한 투자안을 선호하는 경향을 위험회피(Risk Aversion)심리라고 한다. 투자자들이 더 위험회피적일수록 금융상품의 가격이 동일한 평균 보수를 갖는 무위험 채권보다 낮아진다.','','ㅇㅎㅎㅍㅅㄹ','{}'::text[]),
(427,'유동비율','단기채무에 충당할 수 있는 유동자산이 얼마나 되는가를 평가하여 기업의 단기지급능력을 판단할 수 있는 대표적 지표로서 유동비율이 높을수록 단기지급능력이 양호하다고 볼수 있으나 과다한 유동자산 보유는…','단기채무에 충당할 수 있는 유동자산이 얼마나 되는가를 평가하여 기업의 단기지급능력을 판단할 수 있는 대표적 지표로서 유동비율이 높을수록 단기지급능력이 양호하다고 볼수 있으나 과다한 유동자산 보유는 자산운용 효율성을 떨어뜨려 수익성을 저해한다. 유동비율 = 유동자산/유동부채 × 100 유동성유동성(Liquidity)이란 자산을 가치의 손실 없이 얼마나 쉽고 빠르게 현금으로 바꿀 수 있는지를 나타내는 개념이다. 유동성은 전환대상 자산의 양과 질, 시장의 형성 정도, 거래방법, 재융자의 가능성 등에 따라 그 정도가 달라진다. 이러한 유동성 개념은 위와 같은 본래의 의미로부터 파생되어 다음의 두 가지 형태로도 사용된다. 첫째로 유동성은 시중의 현금과 다양한 금융상품 중 어디까지를 통화로 정의할지 구분하는 기준으로 사용된다. 우리나라에서는 유동성이 높은 정도에 따라 통화 및 유동성 지표를 현금통화, M1, M2, Lf, L로 구분한다. 둘째로 유동성은 현금을 비롯하여 유동성이 높은 통화 그 자체와 같은 뜻으로 사용되기도 한다. “시중의 풍부한 유동성”, “한국은행이 실시한 유동성 공급 정책” 등과 같은 예에서 유동성은 통화 그 자체를 의미한다.','','ㅇㄷㅂㅇ',ARRAY['통화지표']::text[]),
(428,'유동성 함정','유동성 함정(Liquidity Trap)이란 금리 인하를 통한 확장적 통화정책이 투자나 소비 등 실물경제에 영향을 주지 못하는 상태를 말한다.','유동성 함정(Liquidity Trap)이란 금리 인하를 통한 확장적 통화정책이 투자나 소비 등 실물경제에 영향을 주지 못하는 상태를 말한다. 경제가 침체될 것으로 예상되면 중앙은행은 정책금리를 낮추고 유동성을 공급한다. 그러나 금리를 계속 낮추는데도 경기가 회복되지않고 이 이후에 명목이자율을 더 이상 낮출 수 없어 확장적 통화정책을 통한 경기 진작은 어려워지는데 이를 유동성 함정에 빠졌다고 표현한다.','','ㅇㄷㅅㅎㅈ',ARRAY['유동성']::text[]),
(429,'유동성리스크','거래 일방이 일시적인 자금부족으로 인해 정해진 결제 시점에서 결제의무를 이행하지 못함에 따라 거래상대방의 자금조달 계획 등에 악영향을 미치게 되는 위험을 말한다.','거래 일방이 일시적인 자금부족으로 인해 정해진 결제 시점에서 결제의무를 이행하지 못함에 따라 거래상대방의 자금조달 계획 등에 악영향을 미치게 되는 위험을 말한다. 유동성 리스크는 거래상대방이 지급기일이 지난 이후 채무를 결제할 수 있다는 점에서 거래상대방이 파산하여 채권 회수가 영원히 불가능한 신용리스크와 차이가 있으나 실제로는 그 구별이 쉽지 않다.','','ㅇㄷㅅㄹㅅㅋ',ARRAY['신용위험(신용리스크)']::text[]),
(430,'유동성커버리지비율','유동성커버리지비율(LCR; Liquidity Coverage Ratio)은 단기 유동성 규제비율로서 은행이 유동성 부족에 대비하여 보유한 고유동성자산 규모를 30일간의 유동성스트레스 시나 리오…','유동성커버리지비율(LCR; Liquidity Coverage Ratio)은 단기 유동성 규제비율로서 은행이 유동성 부족에 대비하여 보유한 고유동성자산 규모를 30일간의 유동성스트레스 시나 리오 하에서 예상되는 순현금유출액으로 나눈 비율이다. LCR의 산식은 ‘고유동성자산 / ㅇ 향후 30일간 순현금유출액(현금유출액 - 현금유입액) × 100’이다. 분자의 고유동성자산은 현금은 물론 정부 및 중앙은행이 발행하는 채무증권, 은행이 중앙은행에 예치한 지급준비금 등으로 구성된다. 분모의 순현금유출액은 30일 동안의 심각한 위기상황에서 발생할 것으로 예상되는 현금유출액에서 현금유입액을 차감하여 산출한다. 일반은행이 준수해야 하는 LCR 규제비율은 2015년 80%에서 2019년 100%로 점진적으로 도입되었다. 코로나19 사태 이후 금융권의 가계대출 및 기업 자금 공급 확대를 위해 2020년 일시적으로 기존 100%에서 85%로 인하하였으나 2022년부터 단계적 상향을 통해 2025년 7월 말 현재 100%를 준수하여야 한다.','','ㅇㄷㅅㅋㅂㄹㅈㅂㅇ',ARRAY['유동성리스크','순안정자금조달비율']::text[]),
(431,'유럽부흥개발은행(EBRD)','EBRD(European Bank for Reconstruction and Development)는 중·동부 유럽 국가 의 시장경제체제로의 전환 촉진과 경제개발 지원을 목적으로 1991년 3월…','EBRD(European Bank for Reconstruction and Development)는 중·동부 유럽 국가 의 시장경제체제로의 전환 촉진과 경제개발 지원을 목적으로 1991년 3월 설립된 국제금융기구로서 영국 런던에 본부를 두고 있다. 주요 업무는 역내 회원국에 대한 생산적이고 경쟁적인 민간부문의 활동 지원, 경제개발을 위한 역내외 자본 및 선진기술 동원, 경쟁여건 조성과 생산성 향상을 위한 투자 촉진, 개발사업계획 관련 기술지원 등이다. 재원은 자본금, 채권 발행 및 차입금으로 조성되는 일반재원과 출연을 통한 특별재원으로 조달하고 조직은 총회, 이사회 및 총재를 비롯한 집행부로 구성되어 있다. 2025년 7월 말 현재회원국은 총 77개국이며 역내 국제기구인 유럽연합(EU)과 유럽투자은행(EIB; European Investment Bank)에도 회원자격을 부여하고 있다. 우리나라는 창립회원국으로 참여하고 있다.','','ㅇㄹㅂㅎㄱㅂㅇㅎ()',ARRAY['유럽연합(EU)']::text[]),
(432,'유럽연합(EU)','유럽연합(EU; European Union)은 1991년 12월 마스트리히트 유럽이사회에서 유럽공동체(EC) 12개국 정상이 유럽통합의 방향과 주요 원칙에 합의한 뒤, 1992년 2월…','유럽연합(EU; European Union)은 1991년 12월 마스트리히트 유럽이사회에서 유럽공동체(EC) 12개국 정상이 유럽통합의 방향과 주요 원칙에 합의한 뒤, 1992년 2월 마스트리히트조약(Treaty on European Union)에 서명하고 1993년 11월 동 조약이 발효되면서 종전의 유럽공동체를 계승하는 지역공동체로 공식 출범하였다. 창설 목적은 유럽 내단일시장 구축 및 단일통화 실현을 통한 유럽의 경제와 사회발전 촉진, 공동외교안보정책을 통한 국제무대에서의 유럽의 이익 제고, 유럽연합 시민권제도 도입에 의한 회원국 국민의 권리와 이익 보호 등이다. 회원국은 1995년 1월 3개국이 추가 가입한 데 이어 동유럽 체제전환국들이 가입하면서 점차 늘어났으나 2020년 1월 영국이 EU에서 탈퇴함으로 써 2025년 현재 총 27개국의 회원국이 있다. 유럽연합의 주요 기구는 회원국 정상들의 유로달러(Euro dollar) 회의체인 유럽이사회(European Council), 각종 정책 입안 및 집행을 담당하는 집행위원회(European Commission), 회원국 간 문제해결을 위한 장관들의 회의체인 각료이사회 (CEU), 유럽의회(EP) 등이며 그 외에 유럽사법재판소, 유럽회계감사원, 지역위원회, 유럽중앙은행(ECB), 유럽투자은행 등이 있다. 유럽연합은 유럽의회가 입법부, 유럽사법재판소가 사법부, 집행위원회가 행정부의 역할을 하는 등 일반적인 국제기구와는 달리 독자적인 법령 체계와 입법·사법·행정 기능을 갖추고 있다.','','ㅇㄹㅇㅎ()',ARRAY['유럽중앙은행(ECB)','마스트리히트조약']::text[]),
(433,'유럽중앙은행(ECB)','유럽연합(EU)의 통화정책을 수행하는 중앙은행으로서 1994년에 설립된 유럽통화기구 (EMI)를 승계하여 1998년 6월 출범하였으며 독일 프랑크푸르트에 본부를 두고 있다.','유럽연합(EU)의 통화정책을 수행하는 중앙은행으로서 1994년에 설립된 유럽통화기구 (EMI)를 승계하여 1998년 6월 출범하였으며 독일 프랑크푸르트에 본부를 두고 있다. 유럽중앙은행(ECB; European Central Bank)의 주요 목적은 유로화를 사용하는 유럽국가 지역인 유로존(eurozone)의 물가를 안정시키는 것이며 유로화 발행의 독점적인 권한 을 갖고 있다. 지폐가 아닌 동전의 경우에는 유럽중앙은행의 감독하에 각 나라가 발행할수 있다. 유럽중앙은행은 1999년 1월 1일부터 유로존의 단일 통화정책 권한을 행사하였으며, 정책 최상위 의사결정기구인 Governing Council은 ECB 집행이사회(Executive Board)의 6명과 유로존 회원국 중앙은행 총재들로 구성되고, 연 8회 정책금리를 결정한다.','','ㅇㄹㅈㅇㅇㅎ()',ARRAY['유럽연합(EU)']::text[]),
(434,'유로달러(Euro dollar)','미국 외의 국가에 소재하는 은행에 예치된 미국 달러화를 말하는데, 런던 등 주요 금융시장에서 많이 거래되고 있다.','미국 외의 국가에 소재하는 은행에 예치된 미국 달러화를 말하는데, 런던 등 주요 금융시장에서 많이 거래되고 있다. 유로달러시장의 중심은 은행 간 예금시장으로서 은행 및 브로커들로 구성되어 있다. 1950년대부터 미·소 간 냉전격화에 따라 동유럽 공산국가의 은 행들이 미국 내 은행에 예치했던 달러화 예금을 유럽으로 이체한 데서 비롯되었다. 이후미국의 국제수지 적자가 누적되면서 대규모의 달러 자금이 유럽에 유입된 데다, 1970년대의 오일쇼크 당시 OPEC 국가들이 오일달러를 유로은행에 예치(동 자금은 유로은행의 신디케이트론을 통해 무역수지 적자국으로 환류)함으로써 크게 증가하였다. 유로달러는 은행의 금융·외환거래 및 무역금융의 원활화, 국제유동성 증대에 크게 이바지하였으나 보유자의 수익 추구를 위해 국경을 넘어 자유롭게 자금의 예치나 대출이 이루어지는 특성이 있다. 이 때문에 유로달러는 세계 각지의 금리 차이나 환율 변동에 의한 차익을 찾아 빠르게 이동하는 핫머니(hot money)의 성격을 가지고 있으며, 따라서 국제적 금융교란을 일으킬 위험성을 내포하고 있다.','','ㅇㄹㄷㄹ()',ARRAY['유로마켓(Euro market)']::text[]),
(435,'유로마켓(Euro market)','뉴욕, 동경 등 선진국의 국제금융시장에 대비되는 순수한 의미의 국제금융시장으로, 어떤 통화로 표시된 자금이 해당 통화 발행국 이외의 국가에서 거래되는 시장이다.','뉴욕, 동경 등 선진국의 국제금융시장에 대비되는 순수한 의미의 국제금융시장으로, 어떤 통화로 표시된 자금이 해당 통화 발행국 이외의 국가에서 거래되는 시장이다. 따라서 국내시장으로부터 독립된 시장이라는 특성을 갖고 있으며 Euro dollar, Euro currency, Euro bond 등 여러 하부 시장으로 구성되어 있다. 유로마켓은 Euro dollar 거래에 힘입어 발전하였으며, 당초에는 은행의 달러 자금을 중심으로 한 Euro dollar 시장 또는 Euro currency 시장의 성격이 강하였으나 1980년대 들어 증권화가 진전됨에 따라 Euro bond 시장의 비중이 확대되었다. 유로마켓은 각국 정부의 규제나 간섭에서 벗어나 비교적 자유롭게 거래를 할 수 있다는 장점을 바탕으로 금융 혁신과 기법의 발전을 촉진하며 범세계적인 확산을 가져다주었다. 유로마켓의 확산은 1980년대 이후의 세계적인 금융혁신을 촉진하고 나아가 각국 금융시장의 개방과 효율화를 촉진하는 등 금융의 세계화에도 기여하였다.','','ㅇㄹㅁㅋ()',ARRAY['유로달러(Euro dollar)']::text[]),
(436,'유통시장','유통시장(또는 제2차 시장, Secondary Market)은 이미 발행된 채권, 주식 등 유가증권이 투자자들 사이에서 매매되는 시장을 말한다.','유통시장(또는 제2차 시장, Secondary Market)은 이미 발행된 채권, 주식 등 유가증권이 투자자들 사이에서 매매되는 시장을 말한다. 유통시장은 발행시장에서 발행된 유가증권의 시장성과 환금성을 높여주고 자유경쟁을 통해 공정한 가격을 형성하는 기능을 한다. 채권 유통시장은 장외시장과 장내시장으로 구분된다. 현재 대부분의 채권거래는 장외시장에서 주로 증권회사의 단순중개를 통하여 이루어지고 있다. 장내시장으로는','','ㅇㅌㅅㅈ','{}'::text[]),
(437,'은선','한국거래소 내에 일반채권시장과 국채전문유통시장이 개설되어 있다.','한국거래소 내에 일반채권시장과 국채전문유통시장이 개설되어 있다. 일반채권시장에서 는 전환사채와 소액 국공채의 장내거래가 의무화되어 있어 채권 거래가 비교적 활성화되어 있다. 국채전문유통시장에서의 거래는 국고채전문딜러의 지속적이고 유효한 호가 제시를 통한 시장조성 의무 강화 등의 제도 개선 노력에 힘입어 증가하고 있다. 주식 유통시장에는 유가증권시장(코스피시장), 코스닥시장, 코넥스시장 및 K-OTC시장이 있다. 이 중 K-OTC시장은 장외시장이며, 나머지는 한국거래소에서 개설·운영하는 장내시장이다. 주식이 장내시장에서 매매되기 위해서는 상장이라는 등록 절차를 거쳐야 한다. 코스닥시장은 유망 중소기업, 벤처기업 등이 진입하는 시장이다. 코넥스시장은 설립 초기 중소기업에 특화된 시장으로, 2013년 7월 개설 당시에는 코스닥시장의 하부시장 형태였으나, 2013년 9월 별도시장으로 분리되었다. K-OTC시장에서는 비상장 주식이 거래된다.','','ㅇㅅ',ARRAY['숨은 그림(은화)']::text[]),
(438,'은행경영공시제도','은행의 건전성을 유지하기 위해서는 감독당국의 직접적인 감독 이외에 예금자, 채권자 및주주 등 이해관계자에 의한 시장규율(market discipline)이 중요하다.','은행의 건전성을 유지하기 위해서는 감독당국의 직접적인 감독 이외에 예금자, 채권자 및주주 등 이해관계자에 의한 시장규율(market discipline)이 중요하다. 이에 따라 은행은 이해관계자에게 금융기관에 관한 중요한 정보를 정기적으로 공시한다. 「은행업 감독규정」에 따르면 은행은 연 결산시 결산일 이후 3개월 이내, 분기별 가결산은 결산일 이후 2 개월 이내에 공시하도록 되어 있다. 공시 내용은 조직 및 인력, 재무 및 손익, 자금조달·운용, 건전성·수익성·생산성 등 경영지표, 경영방침 및 리스크 관리 등에 관한 사항을 포괄한다.','','ㅇㅎㄱㅇㄱㅅㅈㄷ','{}'::text[]),
(439,'은행인수어음(BA)','은행인수어음(BA; Banker’s Acceptance)은 은행의 단기무역신용공급방식의 하나로 수출입대금결제를 위해 발행된 환어음을 은행이 인수(accept)하는 것을 말하며, 은행이 어음상의…','은행인수어음(BA; Banker’s Acceptance)은 은행의 단기무역신용공급방식의 하나로 수출입대금결제를 위해 발행된 환어음을 은행이 인수(accept)하는 것을 말하며, 은행이 어음상의 지급의무를 부담한 것이므로 그 신용도가 높아 시장에서 자유로이 양도되고 자산보유의 형태로도 이용되고 있다. 통상 어음발행인이 인수은행에 매입을 신청하고 할인받는 것이 관행으로 되어 있으며, 미국에서는 일반적으로 인수은행이 BA를 만기일까지 보유하지 않고 유통시장에 매각함으로써 안정성과 유동성이 뛰어난 독특한 시장이 형성되는데 이를 은행인수어음시장이라 한다. 이구환신','','ㅇㅎㅇㅅㅇㅇ()','{}'::text[]),
(440,'을기금(Capital B)','외국은행 국내지점의 동일인 및 동일계열기업군 여신한도 등 은행법상의 영업규제와 관련하여 자기자본을 확대해줌으로써 여신기능이 원활히 수행될 수 있도록 하기 위한 명목상의 자본금으로 대차대조표에는…','외국은행 국내지점의 동일인 및 동일계열기업군 여신한도 등 은행법상의 영업규제와 관련하여 자기자본을 확대해줌으로써 여신기능이 원활히 수행될 수 있도록 하기 위한 명목상의 자본금으로 대차대조표에는 나타나지 않는다. 현재 을기금은 「은행업 감독규정」 제 11조에 의거 외국은행 국내지점이 외화자금을 환매조건부로 한국은행에 매각하여 보유· 운용하는 원화자금과 외은지점이 자행의 본점 또는 국외지점으로부터 상환기간이 1년을 초과하는 조건으로 차입한 자금 중 국내에서 운용하는 자금(본지점 장기차입금)을 합산한 것으로 하되 대차대조표상 자본총계의 200%를 초과할 수 없도록 규정하고 있다.','','ㅇㄱㄱ()',ARRAY['갑기금(Capital A)']::text[]),
(441,'의중임금','의중임금이란 유보임금이라고도 하는데 특정 근로자로 하여금 노동을 공급하게 하기 위 ㅇ 해 지불해야 할 최소한의 임금을 말한다.','의중임금이란 유보임금이라고도 하는데 특정 근로자로 하여금 노동을 공급하게 하기 위 ㅇ 해 지불해야 할 최소한의 임금을 말한다. 다시 말해 노동을 공급할 의사가 있는 근로자가 받고자 하는 최소한의 임금이라고 할 수 있다. 따라서 취업자들은 현직에서 받는 임금이 자신들이 염두에 두고 있던 임금보다 높은 사람들이다. 의중임금은 실업기간에 중요한 영향을 미친다. 구직활동기간을 종료시키는 경로는 두 가지인데 하나는 구직활동을 포기하고 비경제활동 상태로 전환하는 경우이고 다른 하나는 취업을 하는 경우이다. 후자는 자신에게 제시된 임금이 자신의 유보임금보다 높을 때 발생한다. 따라서 다른 조건이 같을 경우 유보임금이 높을 때 실업기간은 길어지게 된다.','','ㅇㅈㅇㄱ',ARRAY['통상임금']::text[]),
(442,'이구환신','이구환신은 중국 정부가 소비를 촉진하여 내수를 확대하고 생산활동을 활성화하기 위해시행한 정책이다.','이구환신은 중국 정부가 소비를 촉진하여 내수를 확대하고 생산활동을 활성화하기 위해시행한 정책이다. 이구환신(以舊換新)은 한자로 ‘오래된 것을 새로운 것으로 교체한다’라는 뜻이다. 소비자에게 금융지원을 하거나 판매기업에 보조금 지급을 통해 오래된 소비재 (예: 가전제품, 자동차 등)를 새로운 제품으로 교체하도록 유도하는 정책이다. 중국 정부는 2009~10년 글로벌 금융위기 시기 및 2024~25년에 둔화된 소비를 진작하고자 이구환신정책을 실시하였다. 동 정책은 에너지 소비가 높고 오염물질 배출량이 많은 오래된 가전제품, 자동차를 최신 기술 탑재 제품으로 교체토록 한다는 점에서 환경보호, 기술혁신이 라는 더 큰 목적을 추구하는 측면도 있다. 한편, 우리나라도 소비촉진, 환경보호 등을 위해 오래된 디젤자동차 교체 촉진, 유류세 인하 등의 정책을 추진한 바 있다.','','ㅇㄱㅎㅅ',ARRAY['쌍순환 전략']::text[]),
(443,'이슬람금융','이슬람금융이란 이슬람교 율법인 샤리아(Shariah)에 따라 행해지는 금융을 말한다.','이슬람금융이란 이슬람교 율법인 샤리아(Shariah)에 따라 행해지는 금융을 말한다. 이 슬람교 율법인 샤리아에서는 이자금지, 도박금지, 불확실거래금지 등을 명시하고 있어서 이슬람금융은 그 운용방식이 일반금융과는 다른데, 우선 모든 이슬람 금융상품 및 금융거래는 사전에 이슬람 법학자들로 구성되는 샤리아위원회의 샤리아 적합성 인증이 필수적이다. 또한 이슬람 은행에서는 이자 개념을 탈피하기 위하여 실물자산을 개재한 거래(매매나 리스)와 수익을 배분하는 거래(신탁이나 출자) 등의 방식을 이용하고 있다. 한 편 이슬람금융의 상품거래 형태로는 무라바하(Murabahah), 이스티스나(Istisna), 이자라 (Ijarah) 등이 있고, 투자 형태로는 무다라바(Mudharabah), 무샤라카(Musyarakah) 등 이 있다. 이 외의 응용 형태 금융거래로서 보험과 유사한 타카풀(Takaful), 금융 투자 상품으로 수쿠크(Sukuk, 이슬람채권) 등이 있다.','','ㅇㅅㄹㄱㅇ',ARRAY['수쿠크']::text[]),
(444,'이연차액결제','이연차액결제는 일정 기간중 지급결제시스템에 참가하는 기관의 양자간 또는 다자간에 지급할 총금액과 수취할 총금액을 모아서 상계 처리한 차액을 일정 시점 후에 결제하는 방식이다.','이연차액결제는 일정 기간중 지급결제시스템에 참가하는 기관의 양자간 또는 다자간에 지급할 총금액과 수취할 총금액을 모아서 상계 처리한 차액을 일정 시점 후에 결제하는 방식이다. 금융기관의 순포지션은 해당 금융기관이 수취한 지급지시 금액의 합계에 서 송부한 지급지시 금액의 합계를 차감하여 산출한다. 이연차액결제방식은 상계한 차액만을 결제하면 되므로 결제유동성을 절감할 수 있는 장점이 있으나 결제시점까지 결제가 완료되지 않아 신용리스크에 노출되는 문제가 있다. 현재 우리나라의 소액결제시스템이중통화채(Dual Currency Bond) (어음교환, 타행환, 전자금융 등)은 이연차액결제 방식으로 최종 결제가 이루어지고 있다.','','ㅇㅇㅊㅇㄱㅈ',ARRAY['신용위험(신용리스크)']::text[]),
(445,'이자보상배율','영업이익을 이자비용으로 나눈 값으로 측정하는 지표이다.','영업이익을 이자비용으로 나눈 값으로 측정하는 지표이다. 이는 영업활동에 의한 이익으로 이자비용을 어느 정도나 부담할 수 있는 지, 즉 기업의 이자부담능력을 평가하는 지표로 이용된다. 동 지표가 높을수록 이자부담능력이 좋다고 할 수 있으며, 동 지표가 1보다 작으면 영업이익 전체로도 금융비용을 충당할 수 없는 상태를 의미한다. 다만 우리나라와 같이 기업의 이자수익이 상당한 규모에 이르는 경우 기업의 실질적인 금융비용 부담능력이 과소평가될 가능성이 높으므로 이자비용에서 영업외이익으로 분류되는 수입이자를 차감한 순금융비용을 이용하여 산출한 순이자보상배율을 보조지표로 활용하는 것이 좋다. 한편 같은 개념으로 이자보상비율이 있는데 이는 이자보상배율에 100을 곱하여 %로 표시한 것이다.','','ㅇㅈㅂㅅㅂㅇ','{}'::text[]),
(446,'이전소득수지','이전소득수지는 국제수지표상 경상수지를 구성하는 항목 중의 하나로 거주자와 비거주자사이에 무상으로 주고받는 거래의 수지를 말한다.','이전소득수지는 국제수지표상 경상수지를 구성하는 항목 중의 하나로 거주자와 비거주자사이에 무상으로 주고받는 거래의 수지를 말한다. 이러한 거래에는 재외교포가 국내 친지에게 보내는 개인송금, 국외 자선단체의 기부금이나 구호물자, 국제기구 출연금 등이 포함된다.','','ㅇㅈㅅㄷㅅㅈ',ARRAY['경상수지','국제수지(BOP)']::text[]),
(447,'이중통화채(Dual Currency Bond)','국제 간 환율 및 금리 전망을 바탕으로 채권 발행 통화와 상환 통화를 달리하여 발행하는 채권을 말한다.','국제 간 환율 및 금리 전망을 바탕으로 채권 발행 통화와 상환 통화를 달리하여 발행하는 채권을 말한다. 발행방식은 기본적으로 채권의 발행은 저금리 통화(강세통화)로, 상환은 고금리 통화(약세통화)로 한다. 이중통화채의 발행으로 발행자는 금리부담을 경감할 수있고 투자자는 상환 통화가 미리 정한 환율보다 강세가 될 경우 환차익을 기대할 수 있는 장점이 있다. 예컨대 액면과 이자는 미 달러화로 표시되고, 상환은 엔화나 스위스 프랑화로 하는 방식의 채권을 가리킨다. 달러화가 강세인 때에 주로 사용된다. 일본의 경우 저금리 상태가 지속되면서 자국 통화 표시 채권의 수익률이 지속적으로 낮아지는 상황에서 채권의 쿠폰을 금리가 높은 통화로 지급하는 방식의 이중통화채가 활발하게 발행되었다. 최근에는 역이중통화채(reverse dual currency bond)라는 발행 형태가 등장하였는데 이는 기채 통화와 상환 통화는 같으나 이자 지급은 발행 당시의 고금리 통화로 이루어지는 형태를 말한다. 이밖에 채권의 원금은 두 나라 통화로 수수되고 이자지급은 두 나라 환율에 연결되어 있는 혼합이중통합채권도 있다.','','ㅇㅈㅌㅎㅊ()','{}'::text[]),
(448,'이차전지','외부의 전기 에너지를 화학 에너지의 형태로 전환하여 내부에 저장해 두었다가 필요할때 재사용할 수 있도록 만들어진 장치가 이차전지(Secondary Cell)이다.','외부의 전기 에너지를 화학 에너지의 형태로 전환하여 내부에 저장해 두었다가 필요할때 재사용할 수 있도록 만들어진 장치가 이차전지(Secondary Cell)이다. 전기화학 반응을 통해 전기 에너지를 장치 내부에서 직접 만들어내는 일차전지(primary cell)와는 달리외부로부터 전기 에너지를 공급받는 방식이 적용된다는 점에서 이차전지로 통용된다. 다 만 일회용인 일차전지와 달리 충전과 방전을 통해 반복적으로 재사용이 가능하다는 특징을 감안하여 충전식 전지(rechargeable battery)로 불리기도 한다. 이차전지는 충전기술및 저장기능의 획기적인 발전으로 충전을 통한 재사용에 횟수 제한이 대폭 완화되고 사용시간이 크게 늘어나면서 일차전지 시장의 상당 부분을 대체하는 가운데 기존 일차전지가 활용되지 못했던 영역으로까지 사용처가 빠르게 확대되고 있다. 특히 최근에는 스마트폰, 디지털 카메라 등의 휴대용 전자장치 및 소형 가전뿐만 아니라 전기차, 드론 등 이동수단으로까지 활용 사례가 광범위해지고 있다.','','ㅇㅊㅈㅈ','{}'::text[]),
(449,'이표채','국채·금융채·회사채 등의 채권은 이자지급 방법에 따라 할인채(Discount Bond), 이표채 (Coupon Bond), 복리채(Compound Interest Bond) 등으로 구분되는데…','국채·금융채·회사채 등의 채권은 이자지급 방법에 따라 할인채(Discount Bond), 이표채 (Coupon Bond), 복리채(Compound Interest Bond) 등으로 구분되는데 이표채는 채권의 권면에 이표(쿠폰, coupon)가 붙어 있어 이자지급일에 이를 떼어 제시함으로써 이자를 지급받는 채권을 말한다. 통상적으로 만기까지 일정 기간마다 이자를 지급하고 만기에는 원금을 지급하는 가장 일반적인 형태의 채권을 지칭한다. 이표채처럼 일정한 간격을 두고 인구고령화주기적으로 수취하는 채권이자는 투자자의 입장에서 볼 때는 원래의 채권 투자자금 원본의 회수기간이 일부 앞당겨지는 효과를 얻게 된다. 이처럼 이표의 이자수취 만큼 투자자금 회수기간이 단축되는 효과를 감안하여 채권의 만기를 정밀하게 산출한 것을 듀레이션, 즉 평균만기라고 한다. 금리가 1% 변동할 때 채권의 가격은 듀레이션의 배율만큼 증폭되어 변동하기 때문에 유가증권투자에 있어서 매우 중요한 분석도구이다. 한편 이표채와 대비되는 개념으로 할인채와 복리채가 있다. 할인채는 이자의 지급 없이 만기에 원금을 지급하는 채권으로 액면보다 할인된 가격으로 발행되는데, 쿠폰 없이 발행되기 때문에 무이 표채 또는 제로쿠폰채(zero-coupon bond)라고 한다. 복리채는 이자를 중간에 지급하지않고 만기에 원금과 함께 일시에 지급하는 채권을 말한다.','','ㅇㅍㅊ','{}'::text[]),
(450,'익스포저','특정 리스크에 노출되어 있는 금액을 의미하며 리스크 유형에 따라 시장리스크 익스포저, 신용리스크 익스포저 등으로 구분된다.','특정 리스크에 노출되어 있는 금액을 의미하며 리스크 유형에 따라 시장리스크 익스포저, 신용리스크 익스포저 등으로 구분된다. 시장리스크 익스포저는 금리, 환율, 주가 등의 변동에 따른 가치 변동에 따른 손실 가능성에 노출된 금액을, 신용리스크 익스포저는 거래상대방의 신용도 하락, 채무불이행에 따른 경제적 손실 가능성에 노출된 금액을 의미한 다. 따라서 익스포저(Exposure)는 장부가액보다 포괄적인 개념으로, 난내(on-balance sheet) 자산은 일반적으로 재무상태표상 금액이 통상 익스포저와 동일하나 난외(off- balance sheet) 항목은 현재 시점에서 관련 권리·의무가 확정되지 않아 계약의 명목가 액을 익스포저로 사용할 수 없다. 따라서 난외항목의 경우 해당 계약의 명목금액에 해당유형별로 난내자산으로 전환될 확률에 해당하는 신용환산율(CCF; Credit Conversion Factor)을 곱하여 산출한 신용등가액(credit equivalent amount)을 익스포저로 한다. 한 편 익스포저는 발생 가능한 손실 가능액을 측정하지만 발생 가능성(위험가중치)으로 조정하지 않은 중립적인 금액이라는 점에서 위험가중자산과 차이가 있다.','','ㅇㅅㅍㅈ',ARRAY['레버리지비율/단순기본자본비율','위험가중자산/위험가중치']::text[]),
(451,'인구고령화','인간의 평균 수명이 증가하고 출산율이 감소함에 따라 선진국을 중심으로 고령자의 인구 비율이 점차 높아져 가는 현상 또는 그러한 상태를 고령화라고 한다.','인간의 평균 수명이 증가하고 출산율이 감소함에 따라 선진국을 중심으로 고령자의 인구 비율이 점차 높아져 가는 현상 또는 그러한 상태를 고령화라고 한다. 국제 연합(UN)은 총인구에서 65세 이상 인구가 7% 이상일 경우 고령화 사회, 14% 이상일 경우 고령 사회, 20% 이상일 경우 초고령 사회로 구분하였다. 우리나라는 2000년에 고령화사회로, 2018 년에 고령사회로, 2024년에 초고령사회로 진입하였다. 이와 같은 인구의 고령화 현상은 노동력 부족, 생산성 저하 등 노동시장 변화를 야기하여 경제성장을 둔화시키고, 노년 인구 부양비 상승과 연금, 의료, 복지비용 등의 증가 문제를 발생시킬 수 있다. 반면 고령화는 노인의 정치적 영향력 확대, 여가 및 레저 활동 주도계층 변화, 교육제도 재편 등 파급효과가 나타날 수 있을 뿐 아니라 건강약품과 식품산업, 의료서비스, 금융서비스, 레저 또는 노인주택산업 등의 고령친화산업 분야의 성장 등 산업구조변화를 가져올 수 있다. 우리나라의 고령화속도는 세계에서 유래가 없을 정도로 빠르게 진행되고 있어 고령화 문제의 해결을 위한 사회·경제적인 종합적인 대책이 필요하다.','','ㅇㄱㄱㄹㅎ',ARRAY['합계출산율']::text[]),
(452,'인적자본','개인이 보유한 능력, 기술숙련도, 지식 등을 포괄하는 것으로 노동의 질적 수준을 의미한 다.','개인이 보유한 능력, 기술숙련도, 지식 등을 포괄하는 것으로 노동의 질적 수준을 의미한 다. 인적자본(Human Capital)이란 개념은 1960년대 초에 미국의 농업경제학자인 슐츠 (T. Schultz)가 제시한 것으로, 그는“교육을 통해서 형성되는 능력은 임금, 소득, 저축, 자본형성 등을 근본적으로 변화시킨다”며“경제성장에서 오래 풀리지 않는 수수께끼를 인적자본에 대한 투자라는 개념을 통해서 분명하게 해결할 수 있다”고 인적자본 증가가 경제성장에 중요함을 지적하였다. 인적자본이 경제성장에 미치는 영향은 경제성장이론에서 중요한 연구 분야인데, 전통적인 성장이론에 따르면 GDP성장률은 장기적으로 인구 증가 율과 외생적으로 주어지는 기술진보율에 따라서 결정된다. 반면 1980년대 이후의 신성장이론(new growth theory)에 따르면 인적자본, 내생적 기술발전, 제도 등이 경제성장에 서 중요한 역할을 한다. 생산요소로서의 인적자본은 노동생산성을 높여 직접적으로 경제성장에 기여할 뿐 아니라 물적자본과 결합하여 자본축적에 따라 자본생산성이 하락하는 속도를 늦추는 효과가 있다. 또한 인적자본은 기술혁신의 중요한 요소로서 기술발전 속도 를 높여 경제성장률을 높인다. 부모의 인적자본 증가도 세대 간의 연결을 통해 지속적으로 인적자본을 증가시키며 경제성장률을 높이는 효과가 있다.','','ㅇㅈㅈㅂ',ARRAY['노동생산성/노동생산성지수']::text[]),
(453,'인터넷뱅킹','인터넷뱅킹이란 고객이 자금이체, 계좌조회 등 은행 업무를 인터넷을 통해 원격지에서 처리할 수 있는 금융서비스이다.','인터넷뱅킹이란 고객이 자금이체, 계좌조회 등 은행 업무를 인터넷을 통해 원격지에서 처리할 수 있는 금융서비스이다. 휴대전화 등 모바일기기를 이용하는 모바일뱅킹의 경우도 넓은 의미에서 인터넷뱅킹의 범주에 포함된다. 인터넷뱅킹 서비스는 제공하는 은행마다 서비스 내용이 조금씩 다르지만 대부분 예금조회, 자금이체, 대출 등의 기본적인 금융서 비스 외에도 계좌통합서비스, 기업간(B2B) 상거래 결제서비스 등을 제공하고 있다. 또한 은행은 각종 상담 및 홍보업무처리도 지원하는 등 인터넷뱅킹을 통해 다양한 서비스를 제공하고 있다.','','ㅇㅌㄴㅂㅋ',ARRAY['모바일뱅킹','텔레뱅킹(폰뱅킹)']::text[]),
(454,'인플레이션','물가수준이 지속적으로 상승하는 현상을 인플레이션이라고 한다.','물가수준이 지속적으로 상승하는 현상을 인플레이션이라고 한다. 여기서 물가는 개별상 ㅇ 품의 가격을 평균하여 산출한 물가지수를 의미한다. 인플레이션은 물가상승 지속기간 및상승폭, 제품의 질적 수준 향상 여부, 정부의 가격통제에 따른 암시장 가격 상승 여부와 같은 점을 고려할 때 언제 인플레이션이라고 정의할 것인가에 대해 이견이 있을 수 있다. 통상 연 4~5% 정도의 물가상승률이 관측되면 일반적으로 인플레이션이 발생했다고 판단한다.','','ㅇㅍㄹㅇㅅ',ARRAY['디스인플레이션','디플레이션']::text[]),
(455,'인플레이션감축법(IRA)','인플레이션감축법(IRA; Inflation Reduction Act)은 미국이 높은 인플레이션 상황에 대응하여 국민생활 안정화를 위해 2022년 8월 시행한 법률이다.','인플레이션감축법(IRA; Inflation Reduction Act)은 미국이 높은 인플레이션 상황에 대응하여 국민생활 안정화를 위해 2022년 8월 시행한 법률이다. 보건의료(healthcare), 청정에너지(clean energy), 조세(tax) 분야를 중심으로, 보건의료 부문에는 의약품 가격 인하, 보건비용 부담 완화 등을 통해 가계지출 축소를 지원하는 내용을 담고 있으며, 청정에 너지 분야는 에너지 안보 및 기후변화 대응을 위한 청정에너지경제 구축, 환경오염 감소등을 주요 목표로 설정해 두고 있다. 그리고 동 법에 의거 소요되는 사업비의 충당을 위해증세 등 세수확보 수단을 조세 분야에서 규정하고 있다. 이중 청정에너지 분야에 대하여는 세계 각국의 관심 또한 집중되어 있다. 태양광 패널, 전기차, 배터리 등 재생에너지 산업과 관련하여 미국 정부가 제공하는 각종 세액 공제 및 보조금 혜택을 핵심사항으로 담고 있기 때문이다. 특히 전기차의 경우 세제혜택 대상에 포함되기 위해서는 미국 및 미국과 자유무역협정(FTA)을 체결한 국가에서 채굴·가공된 핵심 광물이 일정 비율 이상 적용된 배터리를 탑재하여야 하고 북미지역에서 최종 조립되어야 하는 조건을 충족해야한다. 이에 따라 미국 중심의 공급망 재편을 목적으로 한다는 명분에도 불구하고 불공정 무역법이라는 비판이 제기되고 있다. 국가별, 기업별 미치는 영향 또한 다양하여 중국산 원료 및소재 의존도가 높은 한국, 일본, 유럽 자동차 기업의 경우 대체 공급망 확보가 중요해진반면 중국 이외 태양광 업체들에게는 보조금 및 세제혜택 수혜대상에서 중국기업이 배제됨에 따라 미국 내 시장점유율을 확대할 수 있는 기회라는 평가가 나오고 있다.','','ㅇㅍㄹㅇㅅㄱㅊㅂ()','{}'::text[]),
(456,'일대일로','일대일로는 아시아·아프리카·유럽을 잇는 중국의 대규모 경제권역 구상으로 2014년 11월중국 개최 아시아태평양경제협력체(APEC) 정상회의에서 당시 시진핑 총서기가 공식적으로 발표하였다.','일대일로는 아시아·아프리카·유럽을 잇는 중국의 대규모 경제권역 구상으로 2014년 11월중국 개최 아시아태평양경제협력체(APEC) 정상회의에서 당시 시진핑 총서기가 공식적으로 발표하였다. 중국의 일대일로 구상은 일대(One Belt)와 일로(One Road)의 두 가지 핵심 무역경로를 제시하고 있다. 이중 ‘일로’는 과거 실크로드와 같은 개념으로 철도를 이용하여 중국 서부에서 유럽까지 연결하는 육상 무역경로를 의미한다. 다른 하나인 ‘일대’는 중국 연안에서 동남아시아, 아프리카, 유럽을 잇는 해상 기반의 무역벨트로 추진된다. 중국은 일대일로를 이용하여 중국의 수출기반을 더욱 다양하고 확고하게 구축해 나감으로 써 참여국들과 두터운 경제적 상호 협력관계를 조성한다는 목표를 일차적으로 내세우고 있다. 그리고 강화된 경제협력 네트워크를 기반으로 정치 및 문화분야까지 교류 촉진을 이끌어냄으로써 중국의 국제적 영향력을 한층 끌어올린다는 장기비전을 담고 있다. 그러나 중국의 글로벌 패권 장악에 대한 경계심과 함께 사업추진 방식과 관련하여 여러 문제점들이 드러나게 되면서 시행 초기의 활력이 점차 약화되는 상황이다. 특히 참여국의 인프라 건설자금이 원조형태가 아닌 빌려주는 차관형식으로 지원되면서 참여국들이 과도한 부채문제를 안게 되었으며 사업시행에 중국 기업과 중국인 노동자의 참여를 조건화함으로써 중국에 대한 의존도가 심화될 것이라는 등의 우려의 평가도 적지 않다. 일반특혜관세','','ㅇㄷㅇㄹ','{}'::text[]),
(457,'일물일가의 법칙','완전경쟁이 이루어질 때 동일한 시기, 동일한 시장에서는 품질이 동일한 상품의 가격이 2 개 이상 형성될 수 없다는 법칙이다.','완전경쟁이 이루어질 때 동일한 시기, 동일한 시장에서는 품질이 동일한 상품의 가격이 2 개 이상 형성될 수 없다는 법칙이다. 즉 동일한 상품은 어느 시장에서든지 가격이 같아지게 된다는 것인데 제본스(Jebons, W. S.)와 엣지워스(Edgeworth, F. Y.)는 무차별의 법칙이라고 하였다. 만일 동일한 시기, 동일한 시장에서 동일한 품질의 상품에 대해 2개 이상의 가격이 형성된다면 모든 사람들이 가장 싼 가격으로 사려고 하기 때문에 그보다 비싼가격을 제시한 판매자는 가격을 인하하지 않을 수 없다. 따라서 가격 차이가 없어지게 되며 하나의 상품에는 하나의 가격만 정해지게 된다. 무역에서도 일물일가의 법칙이 적용될수 있는데 어떤 상품의 가격이 국가별로 다를 때 가격이 상대적으로 싼 나라에서 구입하여 가격이 상대적으로 비싼 나라에 파는 이익 추구의 과정이 계속된다면 결국은 모든 나 라에서 그 상품의 가격은 일치하게 될 것이다. 그러나 현실 세계에서는 일물일가의 법칙이 성립하기 어려운데, 이는 운송비, 보험료 등의 거래비용뿐만 아니라 관세의 영향도 받기 때문이다.','','ㅇㅁㅇㄱㅇㅂㅊ',ARRAY['구매력평가환율']::text[]),
(458,'일반특혜관세','개발도상국의 수출 확대 및 공업화 촉진을 위하여, 선진국이 개발도상국으로부터 수입되는 농수산물, 공산품 및 반제품에 대하여는 아무런 조건 없이 “일반적”으로 무관세 또는 저율의 관세를 부과하는…','개발도상국의 수출 확대 및 공업화 촉진을 위하여, 선진국이 개발도상국으로부터 수입되는 농수산물, 공산품 및 반제품에 대하여는 아무런 조건 없이 “일반적”으로 무관세 또는 저율의 관세를 부과하는 관세 상의 특혜대우를 말한다. 여기서 “일반적”이란 의미는 영연방 특혜, 베네룩스 관세동맹 등 기존의 특혜관세제도와는 달리 지리적으로 여러 개 국가 에 국한되지 않고 범세계적으로 적용된다는 것을 뜻한다. 현재 일반특혜관세를 공여하는 국가로는 미국, 일본, 캐나다, 호주, 뉴질랜드, EC 등이 있다. 이들 특혜공여국은 특혜 대상품목, 특혜 폭, 원산지 기준 등을 정하고 이러한 제반요건을 충족한 경우에 한하여 특혜관세를 적용하고 있다.','','ㅇㅂㅌㅎㄱㅅ',ARRAY['상계관세','할당관세제도']::text[]),
(459,'일중RP제도','일중RP제도는 총액결제시스템에서 중앙은행이 참가기관에게 환매조건부증권매매(RP)를 통해 당일 상환을 조건으로 결제에 가용할 수 있는 일중유동성을 제공하는 방법이다.','일중RP제도는 총액결제시스템에서 중앙은행이 참가기관에게 환매조건부증권매매(RP)를 통해 당일 상환을 조건으로 결제에 가용할 수 있는 일중유동성을 제공하는 방법이다. 총액결제시스템에서는 지급지시를 건별로 결제하기 때문에 참가기관은 결제에 소요되는 유동성을 충분히 확보하여야 하나 영업시간 중에 자금수취와 지급시점의 불균형 등으로 일시적인 결제자금 부족이 발생할 수 있다. 이에 따라 중앙은행은 국채 등 적격증권을 대상으로 환매조건부 증권매매를 통해 일시적인 결제부족자금을 지원함으로써 참가기관들의 실시간 자금결제를 가능하게 한다. 특히 중앙은행의 일중당좌대출 지원 대상이 아닌 비은 행금융기관의 경우 일중유동성 지원은 보통 일중RP를 통해 이루어진다. 한국은행이 운영하는 한은금융망에서도 2012년 2월에 국채 및 통화안정증권의 매매결제대금 지원을 위하여 금융투자회사를 대상으로 일중RP제도가 시행되었다. 한국은행은 금융투자회사가 매입 체결한 채권을 직접 매입하여 일중유동성을 공급하고 해당 영업일에 환매 거래를 통해 자금을 회수한다. 만약 금융투자회사가 당일 중 RP지원 금액을 상환하지 못하면 한국은행 자금조정대출 이율에 1%p를 가산한 벌칙금리를 환매이자율로 하여 매매증권을 매입하여야 한다.','','ㅇㅈㅈㄷ',ARRAY['총액결제시스템','한은금융망(BOK-Wire+)']::text[]),
(460,'일중당좌대출제도','일중당좌대출제도는 한은금융망의 자금결제가 원활히 이루어지도록 은행 참가기관에 대하여 영업시간 중 일시적인 결제부족자금을 실시간으로 지원하는 제도로 2000년 9월 도 입되었다.','일중당좌대출제도는 한은금융망의 자금결제가 원활히 이루어지도록 은행 참가기관에 대하여 영업시간 중 일시적인 결제부족자금을 실시간으로 지원하는 제도로 2000년 9월 도 입되었다. 일중당좌대출은 한국은행에 개설된 참가은행의 당좌예금계좌 잔액을 초과한 지급 또는 결제의 요청이 있는 경우 가용담보 범위 내에서 자동으로 실행되는 방식으로 운용된다. 은행별 일중당좌대출의 한도는 없으나 참가기관의 일중당좌대출에 대한 과도 한 의존을 방지하기 위하여 자유한도(금융기관 자기자본의 25%)를 초과하는 대출금에 대해 이자를 부과하고 있다. 한편 은행이 당일 중 상환마감시각까지 일중당좌대출금을 상환하지 못하는 경우에는 한국은행의 익일물 자금조정대출로 전환하여 지원하고 있다. 한 편 한은금융망에 참가하는 비은행금융기관에 대한 일중유동성 지원은 일중RP를 통해','','ㅇㅈㄷㅈㄷㅊㅈㄷ','{}'::text[]),
(461,'자금결제시스템','자금지급시스템과 연계되어 결제가 이루어지는 외환매매거래나 증권매매거래와 달리 자금을 지급하는 거래 자체는 자금이 예금되어 있는 은행내에서 계좌간 이체만으로도 결제가 완료된다.','자금지급시스템과 연계되어 결제가 이루어지는 외환매매거래나 증권매매거래와 달리 자금을 지급하는 거래 자체는 자금이 예금되어 있는 은행내에서 계좌간 이체만으로도 결제가 완료된다. 따라서 자금결제시스템이란 일반적으로 각 은행 내에서 고객자금의 잔액과 유출입을 관리하는 은행 회계시스템과 동일한 의미를 가진다.','','ㅈㄱㄱㅈㅅㅅㅌ','{}'::text[]),
(462,'자금관리서비스(CMS)공동망','CMS(Cash Management Service)공동망은 금융기관을 통해 대량의 출금 및 입금서비스를 제공하는 지급시스템으로 금융결제원이 1996년 8월부터 가동하였다.','CMS(Cash Management Service)공동망은 금융기관을 통해 대량의 출금 및 입금서비스를 제공하는 지급시스템으로 금융결제원이 1996년 8월부터 가동하였다. 먼저 출금이 체 서비스는 각종 상품 판매대금, 서비스 이용대금, 수업료, 회비 등을 받는 자가 다수의 납부자 예금계좌나 예탁금계좌에서 출금하여 입금받는 업무로서 지로 자동이체와 유사하다. 입금이체 서비스는 각종 상품 구입대금, 배당금, 연금, 급여 등을 보내는 자가 계좌에 서 자금을 인출하여 타 금융기관의 수취인 계좌로 자금을 지급하는 업무로서 지로의 대량지급과 비슷하다. CMS는 각종 사회단체, 학교 및 학원 등을 중심으로 활발히 이용되고 있으며 이를 통해 비교적 저렴한 비용으로 매번 금융기관을 방문하거나 인터넷뱅킹 등을 통해 이체하지 않고 정기적인 대금 수납 및 지급을 처리할 수 있다.','','ㅈㄱㄱㄹㅅㅂㅅ()ㄱㄷㅁ',ARRAY['국민계정체계(SNA)','금융연관비율(골드스미스비율)']::text[]),
(463,'자금조달비용지수(COFIX)','COFIX(Cost of Funds Index)는 은행이 조달한 자금의 평균금리를 나타내는 지수로 은 행 변동금리형 대출의 준거금리로 활용되고 있다.','COFIX(Cost of Funds Index)는 은행이 조달한 자금의 평균금리를 나타내는 지수로 은 행 변동금리형 대출의 준거금리로 활용되고 있다. 은행연합회는 신한, 우리, SC제일, 하나, 국민, 한국씨티, 농협, 중소기업은행 등 국내 8개 은행이 제공하는 수신상품의 금액과 금리를 가중평균하여 신규취급액기준, 잔액기준, 신잔액기준, 단기 COFIX로 구분하여공시한다. 지수산출대상 수신상품은 정기예금, 정기적금, 상호부금, 주택부금, 양도성예금증서, 환매조건부증권매도, 표지어음매출, 금융채(후순위채 및 전환사채 제외) 등이다. 다만 신잔액기준 COFIX를 산출할 때는 상기 수신상품 이외에 기타 예수금, 기타 차입금, 결제성 예금 등을 추가로 포함한다.','','ㅈㄱㅈㄷㅂㅇㅈㅅ()','{}'::text[]),
(464,'자기띠 카드','신용카드나 전화카드와 같이 얇은 플라스틱 카드에 자성체 물질을 띠 모양으로 입히고 필요한 정보를 기록한 카드이다.','신용카드나 전화카드와 같이 얇은 플라스틱 카드에 자성체 물질을 띠 모양으로 입히고 필요한 정보를 기록한 카드이다. 신용카드의 자기띠(Magnetic Stripe)에는 국제표준화기구(ISO)가 정한 기준에 따라 카드 번호, 유효기간, 성명, 제휴코드 등 카드 및 회원에 관한 정보가 담겨져 있다. 이 카드는 데이터 기록 용량이 일반적으로 72byte로써 다량의 데이터 저장이 불가능할 뿐만 아니라 부정 사용에 대한 방지대책이 미흡하고 재저장 능력이 없는 등 기능상의 한계가 드러나고 있어 IC 카드로 교체되고 있다.','','ㅈㄱㄸㅋㄷ',ARRAY['IC 카드']::text[]),
(465,'자기자본비율','자산(= 부채+자기자본) 중에서 자기자본이 차지하는 비중(자기자본비율 = 자기자본/총자본 ×100)을 나타내는 대표적인 재무구조 지표이다.','자산(= 부채+자기자본) 중에서 자기자본이 차지하는 비중(자기자본비율 = 자기자본/총자본 ×100)을 나타내는 대표적인 재무구조 지표이다. 자기자본은 금융비용을 부담하지 않고 기업이 장기적으로 활용할 수 있는 안정된 자본이므로 이 비율이 높을수록 기업 재무구조의 안정성이 높다고 할 수 있다. 우리나라 비금융 영리법인기업 전체(전산업)의 2024년자기자본비율은 49.5%(제조업은 58.8%, 비제조업은 39.5%)이다.','','ㅈㄱㅈㅂㅂㅇ',ARRAY['BIS 자기자본비율']::text[]),
(466,'자기자본이익률(ROE)','자기자본을 이용해 얼마나 효율적으로 이익을 창출했는지를 보여주는 수익성 지표이다.','자기자본을 이용해 얼마나 효율적으로 이익을 창출했는지를 보여주는 수익성 지표이다. 자기자본이익률이 높다는 것은 자기자본에 비해 당기순이익을 많이 내 효율적으로 영업활동을 했다고 평가할 수 있다. 다만 과도한 부채 사용으로 자기자본이익률이 높아진 경우 경영위험이 높아지게 된다.','','ㅈㄱㅈㅂㅇㅇㄹ()',ARRAY['주당순이익(EPS)']::text[]),
(467,'자동안정화장치','경제정책을 입안하고 시행하는 과정은 간단하지 않다.','경제정책을 입안하고 시행하는 과정은 간단하지 않다. 정책의 효율성을 점검해야 하며, 효율성이 입증되었다고 해도 경기상황에 대한 정보수집과 예측, 정책입안, 입법절차 등 을 거쳐 실제로 정책을 시행하기까지 많은 시간이 소요된다. 또한 정책시행에 있어서도','','ㅈㄷㅇㅈㅎㅈㅊ','{}'::text[]),
(468,'자발적 실업','준칙을 따를 것인가 재량에 의존할 것인가도 정책의 효과에 영향을 미친다.','준칙을 따를 것인가 재량에 의존할 것인가도 정책의 효과에 영향을 미친다. 이와 같이 적극적인 경제정책은 여러 가지 한계와 어려움 때문에 상황에 따라서는 더 큰 부작용이 발생할 가능성이 내재되어 있다. 이러한 점을 고려하여 일부 경제학자들은 수동적인 자동안정화장치를 경제정책으로 활용할 것을 권장하였다. 자동안정화장치의 대표적인 예로는 누진세를 꼽을 수 있다. 누진 세제는 경기가 침체할 때 추가적인 입법 과정 없이 자동으로 조세부담을 줄여 경기를 활성화하는 효과가 있다. 반대로 경기가 과열일 때는 과세표준이 늘어나 조세부담이 커지면서 경기를 진정시킬 수 있다. 사회보장제도나 실업보험제도 등 도 자동안정화장치의 예이다. 자동안정화장치는 이처럼 경기변동의 폭을 자동으로 완화해 주는 장점을 갖고 있지만, 경기가 회복되기 시작하여 완전고용 상태로 가는 과정을 더디게 하는 단점도 있다. 경기가 회복되면서 소득세가 늘어나 소비지출이 줄고 실업수당의 지급이 줄어들면서 정부지출이 감소하여 총수요의 증가가 일부 상쇄되기 때문이다.','','ㅈㅂㅈㅅㅇ',ARRAY['마찰적 실업','실망실업자']::text[]),
(469,'자본거래자유화','자본거래의 자유화란 직접투자나 간접투자를 불문하고 정부 혹은 민간이 제3국과의 사이 에 자본을 사용 목적, 방법 등에 대해 어떠한 간섭도 받지 않은 채 자유롭게 공급 또는 도 입하고 나아가 동…','자본거래의 자유화란 직접투자나 간접투자를 불문하고 정부 혹은 민간이 제3국과의 사이 에 자본을 사용 목적, 방법 등에 대해 어떠한 간섭도 받지 않은 채 자유롭게 공급 또는 도 입하고 나아가 동 자본의 원금과 이자의 상환 등에 제한을 받지 않도록 하는 것, 간단히말해 국경 간의 자본이동을 자유화하는 것을 의미한다. 따라서, 자본거래의 자유화는 내국인 또는 국내기업(거주자)의 국외 투자와 외국인 또는 외국기업(비거주자)의 대내 투자양 측면의 자유화를 포괄한다. 자본거래의 자유화는 무역자유화 및 외환거래 자유화와 함 께 일국 경제체제의 개방 및 자유화를 달성하는 가장 중요한 요소이며 최종단계이기도 하다. 우리나라는 1980년대부터 자본거래의 자유화를 추진하기 시작하여 1992년 주식시장을 부분적으로 개방하였고 1996년 OECD 가입과 1997년 외환위기를 계기로 그 속도를 높였다. 특히 외환위기 이후 외국자본의 유치 필요성이 높아지면서 주식, 채권 및 단기금융시장이 순차적으로 개방되었고 1999년 외국환거래법 시행과 함께 국내기업 및 금융기관뿐만 아니라 개인의 외환 및 자본거래도 대폭 자유화하였으며, 2006년 외화거래 자유화를 추진하여 거주자의 해외부동산 투자 자유화, 대외채권회수의무 면제 등 자본거래를 더욱 자유화하였다.','','ㅈㅂㄱㄹㅈㅇㅎ',ARRAY['외국환거래법','경제협력개발기구(OECD)']::text[]),
(470,'자본생산성','재화 및 서비스를 생산하기 위하여 투입한 자본의 양과 그 결과 생산된 산출물의 양의 비율을 자본생산성(Capital Productivity)이라 한다.','재화 및 서비스를 생산하기 위하여 투입한 자본의 양과 그 결과 생산된 산출물의 양의 비율을 자본생산성(Capital Productivity)이라 한다. 이와 비교하여 상품 및 서비스를 생산하기 위하여 투입한 노동의 양과 그 결과 생산된 산출물의 양의 비율은 노동생산성이라한다. 이러한 자본생산성과 노동생산성은 각각 자본과 노동의 평균 생산성을 의미한다. 한편 한계자본생산성은 자본 한 단위를 추가로 투입할 때 얻을 수 있는 산출량의 증가분을 뜻하는 것으로 경제성장 분석에서 유용한 지표로 이용되고 있다.','','ㅈㅂㅅㅅㅅ',ARRAY['노동생산성/노동생산성지수']::text[]),
(471,'자본시장법','증권거래법, 간접투자자산운용업법, 신탁업법 등 자본시장 관련 6개 법률을 통합한 「자본시장과 금융투자업에 관한 법률」(2009년 2월 시행)을 말한다.','증권거래법, 간접투자자산운용업법, 신탁업법 등 자본시장 관련 6개 법률을 통합한 「자본시장과 금융투자업에 관한 법률」(2009년 2월 시행)을 말한다. 동 법률의 목적은 자본시장과 금융투자업에 관한 규제를 개편하여 금융혁신과 경쟁을 촉진하고 대형 투자은행 육성과 자본시장 활성화 등 직접금융시장을 확충함으로써 기존 은행중심의 간접금융체계와 조화를 도모하기 위한 기반을 조성하는 것이었다. 금융투자업을 투자매매업·투자중개업· 집합투자업·신탁업·투자일임업·투자자문업 등 6개로 구분하고 동 업무를 영위하려는 자로 하여금 원하는 업무를 복수 또는 단수로 선택적으로 인가를 받거나 등록을 한 후 영업을 할 수 있도록 하였다. 이와 관련하여 이해 상충 발생 가능성이 높다고 인정되는 금융투자업 간에는 매매에 관한 정보제공 금지, 임직원의 겸직제한, 사무공간 등의 공동이용 제한 등을 의무화하였다. 또한 고유자산 및 운용자산이 각각 2조원 이상, 6조원 이상인 금융투자업자는 의무적으로 사외이사를 선임하고 감사위원회를 설치하도록 하였다. 동 법은 금융투자상품을 포괄주의에 입각하여 원본손실이 발생할 가능성이 있는 모든 금융상품으로 정의하였다. 금융투자상품을 증권, 장내파생금융상품, 장외파생금융상품으로 구분하고 증권은 다시 채무증권, 지분증권, 수익증권, 증권예탁증권, 투자계약증권, 파생결합증 ㅈ 권 등으로 구분하였다.','','ㅈㅂㅅㅈㅂ',ARRAY['간접금융/직접금융']::text[]),
(472,'자본적정성','자본이란 재무상태표상 자산에서 부채를 차감한 금액으로 순자산(net worth)으로 불리기도 하며, 납입자본 및 이익잉여금 등으로 구성된다.','자본이란 재무상태표상 자산에서 부채를 차감한 금액으로 순자산(net worth)으로 불리기도 하며, 납입자본 및 이익잉여금 등으로 구성된다. 자본은 사업을 시작하거나 유지하기위한 핵심 자금으로, 영업활동을 위한 자금조달의 기초가 될 뿐만 아니라 예상치 못한 손실에 대비하는 완충장치 역할을 한다. 이러한 의미에서 금융기관의 자본은 지급청구에 대응할 능력을 유지시키면서 해당 금융기관이 감당할 수 있는 최대 손실규모를 의미하기도 한다. 그러므로 금융기관의 자본적정성은 금융기관이 현재 영위하는 사업 및 형태에 비추어 당해 금융기관의 현재 및 미래의 영업활동을 원활히 지원할 수 있고 향후 발생 가능한 손실을 흡수하는 데 필요한 자본의 보유 정도를 의미한다고 할 수 있다. 한편 감독당국은 각 금융업권의 감독규정을 통해 금융기관의 자본적정성 규제를 운용하고 있는데 은행, 보험회사, 증권회사에 대해 각각 BIS 자기자본비율, 지급여력비율(K-ICS비율), 순자본비율이 일정 기준 이상을 충족하도록 하고 있다.','','ㅈㅂㅈㅈㅅ','{}'::text[]),
(473,'자본적지출','자본재에 대한 사용 가능 햇수(내용연수)의 연장을 목적으로 한 대수선 또는 개보수나 생산성 또는 생산되는 재화의 질과 양을 현저하게 향상시키는 지출을 말한다.','자본재에 대한 사용 가능 햇수(내용연수)의 연장을 목적으로 한 대수선 또는 개보수나 생산성 또는 생산되는 재화의 질과 양을 현저하게 향상시키는 지출을 말한다. 즉 기계, 설비, 구조물 또는 기타 고정자산에 대한 주요 개조나 증축이 이에 해당하며 총고정자본형성(투자)으로 처리한다.','','ㅈㅂㅈㅈㅊ',ARRAY['국내총투자율']::text[]),
(474,'자산건전성 분류','금융기관이 보유자산 등에 대해 건전성 여부를 분석하여 불건전자산의 발생을 예방하고 이미 발생한 불건전자산에 대하여는 조기 정상화를 촉진하게 함으로써 금융기관의 자산운용 건전화를 도모하는 한편…','금융기관이 보유자산 등에 대해 건전성 여부를 분석하여 불건전자산의 발생을 예방하고 이미 발생한 불건전자산에 대하여는 조기 정상화를 촉진하게 함으로써 금융기관의 자산운용 건전화를 도모하는 한편 영업활동에서 발생하는 손실 중 사전에 예상되는 손실에 대한 손실흡수력을 확보하고 있다. 금융기관은 감독당국의 자산건전성 분류기준에 따라 보유자산의 건전성 상태를 매 분기 정기적으로 점검하여 정상, 요주의, 고정, 회수의문, 추정손실의 5단계로 분류하고 이에 상응하는 적정 수준의 대손충당금 등을 적립·유지하여야 한다.','','ㅈㅅㄱㅈㅅㅂㄹ',ARRAY['대손충당금적립비율']::text[]),
(475,'자산유동화','일반적으로 특수목적기구(SPV)가 자산보유자로부터 자산을 양도·신탁 받아 이를 기초로 자산유동화증권(ABS)을 발행하고 해당 유동화자산의 관리·운용·처분에 의한 수익이 나 차입금으로…','일반적으로 특수목적기구(SPV)가 자산보유자로부터 자산을 양도·신탁 받아 이를 기초로 자산유동화증권(ABS)을 발행하고 해당 유동화자산의 관리·운용·처분에 의한 수익이 나 차입금으로 자산유동화증권의 원리금 또는 배당금을 지급하는 일련의 행위를 말한다. 자산유동화(Securitization)는 자산보유자의 신용과 분리하여 유동화자산 그 자체에서 자연실업률발생되는 현금흐름을 바탕으로 자금을 조달하는 금융기법으로서 자산보유자의 재무구조개선, 자금조달 비용 절감, 투자자 확대 등의 장점이 있다. 자산유동화증권은 유동화대상자산에 따라 그 종류가 다양한데 예를 들어 기초자산이 주택담보대출인 경우에는 주택저당증권(MBS), 기초자산이 기업 매출채권인 경우에는 자산담보부 기업어음(ABCP)이라고 한다. 「자산유동화에 관한 법률」에 의한 자산유동화증권 발행기관(SPV)으로는 유동화전문회사, 자산유동화업무를 전업으로 하는 외국법인, 「자본시장과 금융투자업에 관한 법률」상 신탁업자 등이 있다.','','ㅈㅅㅇㄷㅎ',ARRAY['특수목적기구(SPV)','주택저당증권(MBS)']::text[]),
(476,'자연독점','상품의 특성 때문에 시장에서 자연스럽게 생겨난 독점을 말한다.','상품의 특성 때문에 시장에서 자연스럽게 생겨난 독점을 말한다. 자연독점(Natural Monopoly)은 생산규모가 커질수록 생산비용이 계속 낮아지는 규모의 경제(economies of scale)가 존재할 때 발생한다. 규모의 경제가 큰 산업의 경우에는 시장에 먼저 진입하여 대규모 생산능력을 갖춘 선발기업이 가격경쟁력을 바탕으로 다른 후발기업의 시장진 ㅈ 입을 자연스럽게 봉쇄할 수 있다. 예를 들어 지역 주민에게 수돗물을 공급하는 경우 공급자는 도시 곳곳에 수도관을 설치해야 한다. 이때 복수의 공급자가 수돗물을 공급한다면공급자마다 수도관을 설치해야 하는데, 이를 위해서는 막대한 고정비용을 지출해야 한다. 따라서 수돗물을 공급하는 평균비용은 하나의 공급자가 존재할 때 가장 낮다. 전기나 전화 등을 공급하는 경우도 마찬가지이다. 자연독점은 초기 투자비용이 커서 투자비용 회수에 오랜 기간이 걸린다는 특징을 가지고 있다. 자연독점은 생산 면에서는 가장 효율적이 지만, 소비자로서는 독점의 피해가 나타날 수도 있기 때문에 많은 나라에서는 자연독점기업이 적당한 가격을 유지하도록 규제하고 있다.','','ㅈㅇㄷㅈ',ARRAY['규모의 경제']::text[]),
(477,'자연실업률','1968년 프리드먼(M. Friedman)이 처음 제시한 개념으로, 경제의 균형상태에서 상품시장과 노동시장 등의 구조적 요인에 의해 결정되는 실업률을 말한다.','1968년 프리드먼(M. Friedman)이 처음 제시한 개념으로, 경제의 균형상태에서 상품시장과 노동시장 등의 구조적 요인에 의해 결정되는 실업률을 말한다. 이는 노동시장의 구조적·마찰적 요인에 의해 결정되는 실업률로서 영(0)의 실업률을 의미하는 것이 아니라인플레이션이 안정적으로 유지될 수 있는 가장 낮은 수준의 실업률을 의미한다. 실업률과 인플레이션의 관계는 통화론자와 케인즈학파간 오랜 논쟁거리 중의 하나로, 통화론자인프리드먼은 예상치 못한 인플레이션이 발생하는 경우 일시적으로 실업률이 하락할 수는 있으나 장기적으로는 노동자들이 인플레이션을 인지하게 되어 임금상승을 요구하게 됨으로써 장기적으로 인플레이션만 유발할 뿐 실업률은 자연실업률 수준으로 수렴한다고 주장하였다. 반면 케인즈학파 학자들은 낮은 수준의 실업률을 유지하려는 정책적 노력이 높은 수준의 물가상승률을 초래하는데 그치지 않고 물가상승률을 가속시킬 수 있다는 점을 강조하였다. 이와 관련하여 이들이 제시한 NAIRU(Non-Accelerating Inflation Rate of Unemployment; 비가속적인플레이션실업률)는 인플레이션이 상승하거나 하락하지 않고 안정적으로 유지될 수 있는 실업률 수준을 지칭하는 점에서 사실상 프리드먼의 자연실업률과 같은 개념이다.','','ㅈㅇㅅㅇㄹ',ARRAY['실업률갭','필립스곡선']::text[]),
(478,'자원민족주의','석유, 가스, 광물 등 천연자원을 보유한 국가가 이에 대한 소유권과 관리권을 강화하고 이 를 지렛대 삼아 국제사회에 대한 경제적, 정치적 영향력을 확대하는 국가주의적 경향을 자원민족주의라 일컫는다.','석유, 가스, 광물 등 천연자원을 보유한 국가가 이에 대한 소유권과 관리권을 강화하고 이 를 지렛대 삼아 국제사회에 대한 경제적, 정치적 영향력을 확대하는 국가주의적 경향을 자원민족주의라 일컫는다. 자원에 대한 소유권과 관리권을 강화하기 위해 외국기업이 소유하고 있는 자원을 국유화하거나 외국기업의 자국내 자원개발에 대해 조건을 까다롭게하고 국내 자원의 수출량을 제한하는 등의 방식이 대표적인 자원민족주의 행태이다. 자원민족주의는 자국의 국가안보와 이익보호라는 측면에서 과거로부터 계속되고 있는 일종의 이데올로기적 이념주의 한 유형이지만 최근 들어 더욱 강화되는 모습을 보이고 있다. 특히 코로나 위기를 계기로 자원에 대한 안정적 공급망 확보가 중요해진 이후에는 이를 둘러싼 미국과 중국간 경쟁적 갈등이 심화되면서 자원민족주의 경향이 우려 수준에 이르고 있는데 배터리 등 디지털산업 발전에 필수적인 희토류를 대량으로 보유하고 있는 중국 및중남미 국가들의 강력한 생산 및 수출 통제가 대표적 사례이다. 자유재','','ㅈㅇㅁㅈㅈㅇ','{}'::text[]),
(479,'자유무역협정(FTA)','협정을 체결한 국가 간에 상품이나 서비스 교역에 대한 관세 및 무역장벽을 철폐함으로써무역특혜를 서로 부여하는 협정을 말한다.','협정을 체결한 국가 간에 상품이나 서비스 교역에 대한 관세 및 무역장벽을 철폐함으로써무역특혜를 서로 부여하는 협정을 말한다. 자유무역협정(FTA; Free Trade Agreement) 은 그동안 유럽연합(EU)이나 북미자유무역협정(NAFTA) 등과 같이 인접국가나 일정한 지역을 중심으로 이루어졌기 때문에 흔히 지역무역협정(RTA; Regional Trade Agreement) 이라고도 불린다. 자유무역협정은 체결국간 경제통합의 심화정도에 따라 회원국간 관세를 포함하여 각종 무역제한조치를 철폐하는 자유무역협정, 회원국간 역내무역 자유화 외에도 역외국에 대해 관세에 대한 공동보조를 취하는 관세동맹, 회원국간 노동, 자본 등 생산요소의 자유로운 이동이 가능한 공동시장, 회원국들이 독립된 경제정책을 철회하고 단일경제체제하에서 모든 경제정책을 통합 운영하는 완전경제통합 등의 4단계로 구분된다. 자유무역협정은 국가 간 합의된 내용에 대해 무역장벽을 완화하되 제삼국에 대해서 최혜국대우부여를 원칙으로 하는 세계무역기구(WTO)의 다자간무역협정과는 차이가 있다. 한편 자유무역협정은 전통적으로 상품분야의 무역자유화 또는 관세인하에 중점을 두는 경우가 많았으나 최근에는 그 적용 범위가 서비스, 투자, 지적 재산권, 정부조달, 정책 등으로까지 확대되고 있다. 2024년 말 기준 우리나라는 59개국과 21건의 자유무역협정을 체결하였다. ㅈ','','ㅈㅇㅁㅇㅎㅈ()',ARRAY['상계관세']::text[]),
(480,'자유재','희소성이 높지 않고 아무런 대가를 치르지 않아도 무상으로 얻을 수 있는 재화를 말한다.','희소성이 높지 않고 아무런 대가를 치르지 않아도 무상으로 얻을 수 있는 재화를 말한다. 이는 희소성을 가지며 경제적 거래를 통해 얻을 수 있는 경제재(economic goods)의 반대 개념이다. 자유재(Free Goods)는 대가를 치르지 않고서도 얼마든지 원하는 만큼 얻을 수 있기 때문에 경제문제를 일으키지 않으며 희소성의 원칙도 적용되지 않는다. 현실세계에서 자유재는 매우 드물다. 공기, 물, 햇빛 등이 전통적으로 자유재로 고려되었으나 양질의 생수를 높은 비용으로 구매하고, 맑은 공기를 마시기 위하여 휴양림을 찾아가는 등 기존에 자유재로 고려되던 재화들이 상황 변화에 따라 경제재로 변하기도 한다. 일반적으로 재화라고 하면 경제재를 의미하며 통상 경제학은 경제재를 분석대상으로 한다.','','ㅈㅇㅈ',ARRAY['기펜재']::text[]);
